import { useState } from "react";

/**
 * FAQ — Composant réutilisable
 *
 * Props :
 *   faqData  → array  → [{ question: string, answer: string, img: string }]
 *              Si absent, affiche les données par défaut ci-dessous.
 *   title    → string → Titre de la section  (défaut : "FAQs")
 *   subtitle → string → Sous-titre          (défaut : texte générique)
 *
 * Usage :
 *   import FAQ from "./FAQ";
 *   import photo1 from "../assets/photo1.png";
 *
 *   const maFaq = [
 *     { question: "...", answer: "...", img: photo1 },
 *   ];
 *   <FAQ faqData={maFaq} title="Vos questions" subtitle="Tout ce que vous voulez savoir." />
 */

const DEFAULT_FAQ = [
  {
    question: "Comment puis-je accéder à mes documents universitaires ?",
    answer:
      "Connectez-vous à votre compte sur notre plateforme. Une fois connecté, une section dédiée vous donne accès à tous vos documents en quelques clics.",
    img: null,
  },
  {
    question: "Quels types de documents sont disponibles ?",
    answer:
      "Attestations, relevés de notes, certificats et bien plus encore. Tous authentifiés avec QR code pour garantir leur validité.",
    img: null,
  },
  {
    question: "Comment suivre le statut de ma demande ?",
    answer:
      "Notre plateforme vous envoie des notifications instantanées à chaque étape, en temps réel, jusqu'à la validation finale.",
    img: null,
  },
  {
    question: "Puis-je imprimer mes documents ?",
    answer:
      "Oui, directement depuis la plateforme. Assurez-vous d'avoir une imprimante connectée à votre appareil.",
    img: null,
  },
  {
    question: "Comment contacter le support ?",
    answer:
      "Via le formulaire de contact dans votre espace utilisateur. Notre équipe est disponible 24h/24 et 7j/7.",
    img: null,
  },
];

const FAQ = ({
  faqData = DEFAULT_FAQ,
  title = "FAQs",
  subtitle = "Trouvez les réponses aux questions les plus fréquentes sur Etudocs.",
}) => {
  const [openIndex, setOpenIndex] = useState(0);

  const toggle = (index) => {
    setOpenIndex(openIndex === index ? null : index);
  };

  return (
    <section
      id="faq"
      className="mt-20 flex flex-col items-center gap-8 px-8 py-10"
      style={{ backgroundColor: "var(--bg-secondary)" }}
    >
      {/* ── En-tête ── */}
      <div className="flex flex-col items-center gap-4 text-center">
        <h2
          className="text-2xl font-semibold"
          style={{ color: "var(--uac-green)" }}
        >
          {title}
        </h2>
        <p className="text-base max-w-xl" style={{ color: "var(--text)" }}>
          {subtitle}
        </p>
      </div>

      {/* ── Corps ── */}
      <div
        className="w-4/5 mt-8 flex flex-row justify-between gap-14 min-h-[500px] rounded-lg p-4 pb-8"
        style={{ border: "2px solid var(--border)" }}
      >
        {/* Accordéon */}
        <div className="flex flex-col gap-4 w-1/2 mt-4 ml-4">
          {faqData.map((item, index) => (
            <div
              key={index}
              className="rounded-lg p-4 mt-4 cursor-pointer text-xs flex flex-col transition-colors duration-300"
              style={{
                border: `2px solid ${openIndex === index ? "var(--uac-green)" : "var(--border)"}`,
                backgroundColor: "transparent",
              }}
              onClick={() => toggle(index)}
            >
              {/* Question + bouton */}
              <div className="flex flex-row justify-between items-center">
                <p
                  className="font-medium text-sm pr-4"
                  style={{ color: "var(--text)" }}
                >
                  {item.question}
                </p>
                <button
                  className="flex items-center justify-center w-6 h-6 rounded-full text-base font-bold shrink-0 transition-transform duration-300 border-none cursor-pointer"
                  style={{
                    background:
                      openIndex === index ? "var(--uac-green)" : "transparent",
                    color: openIndex === index ? "white" : "var(--text)",
                    transform:
                      openIndex === index ? "rotate(45deg)" : "rotate(0deg)",
                  }}
                  aria-label={openIndex === index ? "Fermer" : "Ouvrir"}
                >
                  +
                </button>
              </div>

              {/* Réponse (accordéon) */}
              <div
                className="overflow-hidden transition-all duration-500 text-xs"
                style={{
                  maxHeight: openIndex === index ? "200px" : "0",
                  marginTop: openIndex === index ? "0.5rem" : "0",
                  color: "var(--text-muted)",
                }}
              >
                <p className="pt-1 leading-relaxed">{item.answer}</p>
              </div>
            </div>
          ))}
        </div>

        {/* Image */}
        <div
          className="w-1/2 flex items-center justify-center overflow-hidden mr-4 mt-8 rounded-lg"
          style={{
            border: "5px solid var(--border)",
            height: "400px",
          }}
        >
          {faqData[openIndex ?? 0]?.img ? (
            <img
              src={faqData[openIndex ?? 0].img}
              alt="illustration FAQ"
              className="w-full h-full object-cover transition-opacity duration-300"
            />
          ) : (
            <div
              className="flex flex-col items-center justify-center gap-2 w-full h-full"
              style={{ color: "var(--text-muted)" }}
            >
              <svg
                xmlns="http://www.w3.org/2000/svg"
                className="w-12 h-12 opacity-30"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={1.5}
                  d="M4 16l4.586-4.586A2 2 0 0111 11h2a2 2 0 011.414.586L19 16m-6-8a2 2 0 100-4 2 2 0 000 4z"
                />
              </svg>
              <span className="text-xs opacity-50">Aperçu</span>
            </div>
          )}
        </div>
      </div>
    </section>
  );
};

export default FAQ;

/**
 * Footer — Composant réutilisable
 *
 * Props :
 *   brandName    → string → Nom de la marque         (défaut : "Etudocs")
 *   brandDesc    → string → Description courte       (défaut : texte Etudocs)
 *   navLinks     → array  → [{ label, href }]        (défaut : liens Etudocs)
 *   legalLinks   → array  → [{ label, href }]        (défaut : liens légaux Etudocs)
 *   contactEmail → string → Email de contact         (défaut : contact@etudocs.com)
 *   socials      → array  → [{ icon, href, label }]  (défaut : 4 réseaux)
 *   ThemeToggle  → node   → Composant toggle thème   (optionnel)
 *
 * Usage minimal :
 *   import Footer from "./Footer";
 *   <Footer />
 *
 * Usage complet :
 *   import Footer from "./Footer";
 *   import ThemeToggle from "../components/dark-light-theme";
 *
 *   <Footer
 *     brandName="MonApp"
 *     contactEmail="hello@monapp.com"
 *     ThemeToggle={<ThemeToggle />}
 *   />
 */

const DEFAULT_NAV_LINKS = [
  { label: "Accueil", href: "#home" },
  { label: "Services", href: "#services" },
  { label: "Comment ça marche ?", href: "#working" },
  { label: "FAQs", href: "#faq" },
];

const DEFAULT_LEGAL_LINKS = [
  { label: "Politique de confidentialité", href: "#privacy" },
  { label: "Conditions d'utilisation", href: "#terms" },
  { label: "Mentions légales", href: "#mentions" },
];

const DEFAULT_SOCIALS = [
  { icon: "fab fa-facebook-f", href: "#", label: "Facebook" },
  { icon: "fab fa-twitter", href: "#", label: "Twitter" },
  { icon: "fab fa-instagram", href: "#", label: "Instagram" },
  { icon: "fab fa-linkedin-in", href: "#", label: "LinkedIn" },
];

/* ── Sous-composant : colonne de liens ── */
const FooterColumn = ({ title, links }) => (
  <div className="flex flex-col gap-2">
    <h6
      className="text-[0.8rem] font-medium mb-2"
      style={{ color: "var(--uac-green)" }}
    >
      {title}
    </h6>
    <ul className="flex flex-col gap-2 list-none p-0 m-0">
      {links.map((link, i) => (
        <li key={i}>
          <a
            href={link.href}
            className="text-[0.8rem] no-underline transition-colors duration-300 hover:opacity-80"
            style={{ color: "var(--text-muted)" }}
            onMouseEnter={(e) =>
              (e.currentTarget.style.color = "var(--uac-green)")
            }
            onMouseLeave={(e) =>
              (e.currentTarget.style.color = "var(--text-muted)")
            }
          >
            {link.label}
          </a>
        </li>
      ))}
    </ul>
  </div>
);

/* ── Composant principal ── */
const Footer = ({
  brandName = "Etudocs",
  brandDesc = "La nouvelle solution pour avoir tous vos documents universitaires en quelques clics.",
  navLinks = DEFAULT_NAV_LINKS,
  legalLinks = DEFAULT_LEGAL_LINKS,
  contactEmail = "contact@etudocs.com",
  socials = DEFAULT_SOCIALS,
  ThemeToggleNode = null,
}) => {
  return (
    <footer className="mt-12 mb-4">
      <div
        className="relative flex flex-row justify-center items-start gap-8 mx-[10%] p-8 rounded-lg"
        style={{
          border: "2px solid var(--border)",
          boxShadow: "0 2px 20px rgba(0,0,0,0.07), 0 1px 4px rgba(0,0,0,0.04)",
          backgroundColor: "var(--bg-secondary)",
          width: "80%",
        }}
      >
        {/* ── Colonne marque ── */}
        <div className="flex flex-col gap-3 max-w-[260px] text-[0.9rem] mr-4">
          <h6
            className="text-[0.8rem] font-medium"
            style={{ color: "var(--uac-green)" }}
          >
            {brandName}
          </h6>
          <p
            className="text-[0.8rem] leading-relaxed"
            style={{ color: "var(--text-muted)" }}
          >
            {brandDesc}
          </p>

          {/* Réseaux sociaux */}
          <div className="flex flex-row gap-4 mt-1">
            {socials.map((s, i) => (
              <a
                key={i}
                href={s.href}
                aria-label={s.label}
                className="transition-colors duration-300"
                style={{ color: "var(--text-muted)" }}
                onMouseEnter={(e) =>
                  (e.currentTarget.style.color = "var(--uac-green)")
                }
                onMouseLeave={(e) =>
                  (e.currentTarget.style.color = "var(--text-muted)")
                }
              >
                <i className={`${s.icon} text-sm`}></i>
              </a>
            ))}
          </div>
        </div>

        {/* ── Navigation ── */}
        <FooterColumn title="Navigation" links={navLinks} />

        {/* ── Mentions légales ── */}
        <FooterColumn title="Mentions légales" links={legalLinks} />

        {/* ── Contact ── */}
        <div className="flex flex-col gap-2">
          <h6
            className="text-[0.8rem] font-medium mb-2"
            style={{ color: "var(--uac-green)" }}
          >
            Contact
          </h6>
          <a
            href={`mailto:${contactEmail}`}
            className="text-[0.8rem] no-underline transition-colors duration-300"
            style={{ color: "var(--text-muted)" }}
            onMouseEnter={(e) =>
              (e.currentTarget.style.color = "var(--uac-green)")
            }
            onMouseLeave={(e) =>
              (e.currentTarget.style.color = "var(--text-muted)")
            }
          >
            {contactEmail}
          </a>
        </div>

        {/* ── ThemeToggle (optionnel) ── */}
        {ThemeToggleNode && (
          <div className="absolute bottom-8 right-20">{ThemeToggleNode}</div>
        )}
      </div>
    </footer>
  );
};

export default Footer;

import { useEffect, useMemo, useState } from "react"
import { AnimatePresence, motion } from "motion/react"
import { clsx } from "clsx"
import { twMerge } from "tailwind-merge"

function cn(...inputs) {
  return twMerge(clsx(inputs))
}

function AnimatedListItem({ children }) {
  const animations = {
    initial: { scale: 0, opacity: 0 },
    animate: { scale: 1, opacity: 1, originY: 0 },
    exit: { scale: 0, opacity: 0 },
    transition: { type: "spring", stiffness: 350, damping: 40 },
  }

  return (
    <motion.div {...animations} layout className="mx-auto w-full">
      {children}
    </motion.div>
  )
}

function AnimatedListBase({ children, className, delay = 1000, ...props }) {
  const [index, setIndex] = useState(0)
  const childrenArray = useMemo(() => {
    const arr = []
    const queue = [children]
    while (queue.length) {
      const item = queue.shift()
      if (Array.isArray(item)) queue.push(...item)
      else arr.push(item)
    }
    return arr
  }, [children])

  useEffect(() => {
    let timeout = null

    if (index < childrenArray.length - 1) {
      timeout = setTimeout(() => {
        setIndex((prevIndex) => (prevIndex + 1) % childrenArray.length)
      }, delay)
    }

    return () => {
      if (timeout !== null) {
        clearTimeout(timeout)
      }
    }
  }, [index, delay, childrenArray.length])

  const itemsToShow = useMemo(() => {
    return childrenArray.slice(0, index + 1).reverse()
  }, [index, childrenArray])

  return (
    <div className={cn("flex flex-col items-center gap-4", className)} {...props}>
      <AnimatePresence>
        {itemsToShow.map((item) => (
          <AnimatedListItem key={item.key}>
            {item}
          </AnimatedListItem>
        ))}
      </AnimatePresence>
    </div>
  )
}

const notifications = [
  { name: "Payment received", description: "Magic UI", time: "15m ago", icon: "💸", color: "#00C9A7" },
  { name: "User signed up", description: "Magic UI", time: "10m ago", icon: "👤", color: "#FFB800" },
  { name: "New message", description: "Magic UI", time: "5m ago", icon: "💬", color: "#FF3D71" },
  { name: "New event", description: "Magic UI", time: "2m ago", icon: "🗞️", color: "#1E86FF" },
]

const duplicated = Array.from({ length: 10 }, () => notifications).flat()

function Notification({ name, description, icon, color, time }) {
  return (
    <figure
      className={cn(
        "relative mx-auto min-h-fit w-full max-w-[400px] cursor-pointer overflow-hidden rounded-2xl p-4",
        "transition-all duration-200 ease-in-out hover:scale-[103%]",
        "bg-white [box-shadow:0_0_0_1px_rgba(0,0,0,.03),0_2px_4px_rgba(0,0,0,.05),0_12px_24px_rgba(0,0,0,.05)]",
        "transform-gpu dark:bg-transparent dark:[box-shadow:0_-20px_80px_-20px_#ffffff1f_inset] dark:backdrop-blur-md dark:[border:1px_solid_rgba(255,255,255,.1)]"
      )}
    >
      <div className="flex flex-row items-center gap-3">
        <div className="flex size-10 items-center justify-center rounded-2xl" style={{ backgroundColor: color }}>
          <span className="text-lg">{icon}</span>
        </div>
        <div className="flex flex-col overflow-hidden">
          <figcaption className="flex flex-row items-center text-lg font-medium whitespace-pre dark:text-white">
            <span className="text-sm sm:text-lg">{name}</span>
            <span className="mx-1">·</span>
            <span className="text-xs text-gray-500">{time}</span>
          </figcaption>
          <p className="text-sm font-normal dark:text-white/60">{description}</p>
        </div>
      </div>
    </figure>
  )
}

export default function AnimatedList({ className, delay = 1500 }) {
  return (
    <div className={cn("relative flex h-[500px] w-full flex-col overflow-hidden p-2", className)}>
      <AnimatedListBase delay={delay}>
        {duplicated.map((item, idx) => (
          <Notification {...item} key={idx} />
        ))}
      </AnimatedListBase>
      <div className="from-background pointer-events-none absolute inset-x-0 bottom-0 h-1/4 bg-gradient-to-t"></div>
    </div>
  )
}

