/*
  ═════════════════════════════════════════════════════════════════
  GetInTouchButton — bouton pill "sweep de contour" (étude de poppr.be)

  FICHIER 100% AUTONOME : aucun import local, aucune bibliothèque
  (React seul), styles embarqués — copier ce fichier tel quel.

  Effet : pill transparent bordé violet. Au survol :
  - le CONTOUR est balayé par 4 disques SVG (stroke-width = largeur
    du bouton, pathLength=1, stroke-dashoffset 1→0) confinés dans un
    clipPath en anneau de 1px — turquoise → jaune → blanc → violet,
    décalés de 0,15s, pendant que le groupe tourne de 90° ;
  - le libellé existe en double : le statique monte (-70%) pendant
    que son clone arrive d'en bas (+70%), easing expo 1,4s.
  Le SVG s'adapte à la largeur mesurée du bouton (ResizeObserver).

  Usage :
      import GetInTouchButton from "./get-in-touch-button";

      <GetInTouchButton href="/contact">Get in touch</GetInTouchButton>
      <GetInTouchButton onClick={fn} colors={{ accent: "#FF6A00" }} />

  Props (toutes optionnelles) :
    children   libellé                (déf. "Get in touch")
    href       rend un <a> ; sinon <button>
    onClick    callback clic
    colors     { accent, sweep1, sweep2, sweep3, text }
    className  classes ajoutées à la racine
  ═════════════════════════════════════════════════════════════════
*/

const DEFAULT_COLORS = {
  accent: "#A374FF", // violet — bordure + fin du sweep
  sweep1: "#17F1D1", // turquoise
  sweep2: "#FFD074", // jaune
  sweep3: "#FAFAF6", // blanc cassé
  text: "#FAFAF6",
};

