/* anneau de 1px : pill extérieur moins pill intérieur (fill-rule evenodd) */
function ringPath(w, h) {
  const r = h / 2;
  const r2 = r - 1;
  return [
    `M ${r} 0 H ${w - r} A ${r} ${r} 0 0 1 ${w - r} ${h} H ${r} A ${r} ${r} 0 0 1 ${r} 0 Z`,
    `M ${r} 1 H ${w - r} A ${r2} ${r2} 0 0 1 ${w - r} ${h - 1} H ${r} A ${r2} ${r2} 0 0 1 ${r} 1 Z`,
  ].join(" ");
}

export default function GetInTouchButton({
  children = "Get in touch",
  href,
  onClick,
  colors = {},
  className = "",
  ...rest
}) {
  const ref = useRef(null);
  const [dims, setDims] = useState({ w: 0, h: 0 });
  const clipId = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const measure = () => {
      const w = el.offsetWidth;
      const h = el.offsetHeight;
      setDims((d) => (d.w === w && d.h === h ? d : { w, h }));
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  const c = { ...DEFAULT_COLORS, ...colors };
  const vars = {
    "--gitb-accent": c.accent,
    "--gitb-s1": c.sweep1,
    "--gitb-s2": c.sweep2,
    "--gitb-s3": c.sweep3,
    "--gitb-text": c.text,
  };

  const { w, h } = dims;
  const circleProps = {
    pathLength: 1,
    cx: w / 2,
    cy: h / 2,
    r: w / 2,
    strokeWidth: w,
  };

  const Tag = href ? "a" : "button";

  return (
    <Tag
      ref={ref}
      className={`gitb ${className}`}
      style={vars}
      {...(href ? { href } : { type: "button" })}
      onClick={onClick}
      {...rest}
    >
