import { useState, useEffect } from "react";

/**
 * ─────────────────────────────────────────────
 *  useTheme — Hook réutilisable (named export)
 * ─────────────────────────────────────────────
 *
 * Gère le thème de l'application (clair / sombre / système).
 * Persiste le choix dans localStorage.
 * Applique automatiquement les CSS variables sur <html>.
 *
 * Usage :
 *   import { useTheme } from "./ThemeToggle";
 *
 *   const { theme, setTheme, toggleTheme } = useTheme();
 *
 * Retourne :
 *   theme        → "light" | "dark" | "system"
 *   setTheme     → (value: string) => void
 *   toggleTheme  → () => void  (bascule light ↔ dark)
 */

const THEMES = {
  dark: {
    "--bg": "#121212",
    "--bg-secondary": "#1e1e1e",
    "--text": "#e0e0e0",
    "--text-muted": "#a0a0a0",
    "--border": "#333",
    "--white": "#1e1e1e",
    "--uac-green": "#4caf50",
    "--benin-yellow": "#c8a800",
  },
  light: {
    "--bg": "#f8fafc",
    "--bg-secondary": "#ffffff",
    "--text": "#1a2744",
    "--text-muted": "#64748b",
    "--border": "#e2e8f0",
    "--white": "#ffffff",
    "--uac-green": "#2e7d32",
    "--benin-yellow": "#f9c000",
  },
};

const getSystemTheme = () =>
  window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";

export function useTheme() {
  const [theme, setTheme] = useState(() => {
    const saved = localStorage.getItem("theme");
    return saved || getSystemTheme();
  });

  useEffect(() => {
    const root = document.documentElement;

    // Résoudre "system" → "dark" ou "light" réel
    const resolved = theme === "system" ? getSystemTheme() : theme;

    root.setAttribute("data-theme", resolved);
    localStorage.setItem("theme", theme);

    const vars = THEMES[resolved] || THEMES.light;
    Object.entries(vars).forEach(([key, val]) =>
      root.style.setProperty(key, val),
    );

    // Écouter les changements système si mode "system" actif
    if (theme === "system") {
      const mq = window.matchMedia("(prefers-color-scheme: dark)");
      const onSystemChange = () => {
        const newResolved = mq.matches ? "dark" : "light";
        const newVars = THEMES[newResolved];
        root.setAttribute("data-theme", newResolved);
        Object.entries(newVars).forEach(([key, val]) =>
          root.style.setProperty(key, val),
        );
      };
      mq.addEventListener("change", onSystemChange);
      return () => mq.removeEventListener("change", onSystemChange);
    }
  }, [theme]);

  const toggleTheme = () =>
    setTheme((prev) => {
      const resolved = prev === "system" ? getSystemTheme() : prev;
      return resolved === "dark" ? "light" : "dark";
    });

  return { theme, setTheme, toggleTheme };
}

/**
 * ─────────────────────────────────────────────
 *  ThemeToggle — Composant réutilisable (default export)
 * ─────────────────────────────────────────────
 *
 * Affiche un sélecteur de thème avec 3 boutons : Clair / Sombre / Système.
 * Peut être placé n'importe où dans l'application.
 *
 * Props :
 *   className   → string  → Classes Tailwind supplémentaires (défaut : "")
 *   showLabels  → boolean → Affiche les labels texte sous les icônes (défaut : false)
 *   size        → "sm" | "md" | "lg" → Taille des boutons (défaut : "md")
 *
 * Usage :
 *   import ThemeToggle from "./ThemeToggle";
 *
 *   // Dans le footer (discret)
 *   <ThemeToggle />
 *
 *   // Dans la navbar (avec labels)
 *   <ThemeToggle showLabels size="lg" className="ml-4" />
 */

const THEME_OPTIONS = [
  { id: "light", icon: "fa-regular fa-sun", label: "Clair" },
  { id: "dark", icon: "fa-regular fa-moon", label: "Sombre" },
  { id: "system", icon: "fa-solid fa-desktop", label: "Système" },
];

const SIZES = {
  sm: { btn: "w-6 h-6 text-xs", icon: "text-[0.75rem]" },
  md: { btn: "w-7 h-7 text-sm", icon: "text-[0.85rem]" },
  lg: { btn: "w-9 h-9 text-base", icon: "text-[1rem]" },
};

export default function ThemeToggle({
  className = "",
  showLabels = false,
  size = "md",
}) {
  const { theme, setTheme } = useTheme();
  const sz = SIZES[size] || SIZES.md;

  return (
    <div
      className={`flex flex-row items-center gap-[3px] rounded-[20px] p-[3px] ${className}`}
      style={{ background: "var(--border)" }}
    >
      {THEME_OPTIONS.map((t) => {
        const isActive = theme === t.id;
        return (
          <button
            key={t.id}
            onClick={() => setTheme(t.id)}
            aria-label={`Mode ${t.label}`}
            title={t.label}
            className={`
              ${sz.btn}
              rounded-full border-none cursor-pointer
              flex flex-col items-center justify-center
              transition-all duration-200
            `}
            style={{
              background: isActive ? "var(--bg-secondary)" : "transparent",
              color: isActive ? "var(--text)" : "var(--text-muted)",
              boxShadow: isActive ? "0 1px 3px rgba(0,0,0,0.15)" : "none",
            }}
          >
            <i className={`${t.icon} ${sz.icon}`}></i>
            {showLabels && (
              <span className="text-[0.6rem] mt-0.5 leading-none">
                {t.label}
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
}

