/*
  ═════════════════════════════════════════════════════════════════
  VoltButton — bouton "pixel flicker" (étude de voltlites.com)

  FICHIER 100% AUTONOME : aucun import local, aucune bibliothèque
  (React seul), styles embarqués — copier ce fichier tel quel.

  Effet : pill mono 42px, cadre noir bordé blanc/10, halo backdrop-blur
  qui se resserre au survol. Au survol :
  - une GRILLE DE PIXELS (6×6, 120px) clignote en teintes chartreuse
    derrière le libellé (setInterval, pas de rAF) ;
  - le libellé ROULE : le mot sort vers le haut en tournant (-20°)
    pendant que son double (data-hover) entre par le bas (30°→0°) ;
  - l'icône fait un swap diagonal (sort ↗, rentre depuis ↙) + le
    conteneur tourne de 45°.

  Usage :
      import VoltButton from "./volt-button";

      <VoltButton href="#contact">Menu</VoltButton>
      <VoltButton hoverLabel="CLOSE" icon="plus" active={open}>MENU</VoltButton>

  Props (toutes optionnelles) :
    children    libellé                      (déf. "View all")
    hoverLabel  texte qui roule au survol    (déf. = children)
    href        rend un <a> ; sinon <button>
    onClick     callback
    icon        "arrow" | "plus" | null      (déf. "arrow")
    active      true → icône en croix (plus tourné 45°), pour un
                bouton MENU/CLOSE
    colors      { text, frame, border, palette: [couleurs pixels] }
    className   classes ajoutées à la racine
  ═════════════════════════════════════════════════════════════════
*/

const DEFAULT_PALETTE = ["#C4D600", "#DFF400", "#8A9900", "#0B0B0B", "transparent", "transparent"];

const CSS = `
.vb {
  --vb-text: #fff;
  --vb-frame: #0B0B0B;
  --vb-border: rgba(255, 255, 255, 0.1);
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  min-width: 140px;
  height: 42px;
  padding: 2px 5px;
  border-radius: 3px;
  border: none;
  background: none;
  font-family: "Roboto Mono", ui-monospace, monospace;
  font-size: 12px;
  font-weight: 500;
  line-height: 1rem;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--vb-text);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.vb > * { pointer-events: none; }

/* halo flouté qui se resserre */
.vb-halo {
  position: absolute;
  inset: -4px;
  border-radius: 3px;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  transition: inset 0.2s;
}
.vb:hover .vb-halo { inset: 0; }

/* cadre noir + grille de pixels */
.vb-frame {
  position: absolute;
  inset: 0;
  overflow: hidden;
  border-radius: 3px;
  background: var(--vb-frame);
  border: 1px solid var(--vb-border);
  transition: all 0.5s;
}
.vb-grid {
  position: absolute;
  top: 50%; left: 50%;
  width: 120px; height: 120px;
  transform: translate(-50%, -50%);
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  grid-template-rows: repeat(6, 1fr);
  opacity: 0;
  transition: opacity 0.6s;
}
.vb:hover .vb-grid { opacity: 1; }

/* contenu */
.vb-content {
  position: relative;
  width: 100%;
  padding: 4px 8px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
}
.vb-label {
  display: block;
  width: 100%;
  overflow: hidden;
  text-align: left;
  line-height: 1;
}
.vb-label > span {
  position: relative;
  display: block;
  line-height: 1rem;
}
.vb-label > span::before {
  content: attr(data-hover);
  position: absolute;
  top: 100%;
  display: inline-block;
  color: currentColor;
  transform: rotate(30deg) translateY(32%);
  transform-origin: left center;
}
.vb-label i {
  display: inline-block;
  font-style: normal;
  transform-origin: left center;
}
@media (hover: hover) {
  .vb:hover .vb-label > span {
    transform: translateY(-100%);
    transform-origin: left top;
    transition: transform 0.5s cubic-bezier(0.66, 0, 0.34, 1);
  }
  .vb:hover .vb-label > span::before {
    transform: rotate(0deg);
    transition: transform 0.5s cubic-bezier(0.66, 0, 0.34, 1);
  }
  .vb:hover .vb-label i {
    transform: rotate(-20deg) translateY(-32%);
    transition: transform 0.5s cubic-bezier(0.66, 0, 0.34, 1);
  }
}

/* icône : swap diagonal + rotation 45° */
.vb-ic {
  position: relative;
  width: 10px; height: 10px;
  flex-shrink: 0;
  overflow: hidden;
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
.vb-ic > span {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
.vb-ic > span:last-child { transform: translate(-100%, 100%); }
@media (hover: hover) {
  .vb:hover .vb-ic { transform: rotate(45deg); }
  .vb:hover .vb-ic > span:first-child {
    transform: translate(100%, -100%);
    transition: transform 0.5s cubic-bezier(0.66, 0, 0.34, 1);
  }
  .vb:hover .vb-ic > span:last-child {
    transform: translate(0, 0);
    transition: transform 0.5s cubic-bezier(0.66, 0, 0.34, 1);
  }
}
/* état actif (ex. menu ouvert) : le plus devient croix */
.vb[data-active="true"] .vb-ic { transform: rotate(45deg); }

@media (prefers-reduced-motion: reduce) {
  .vb *, .vb:hover * { transition: none !important; }
}
`;

function Icon({ kind }) {
