export default function VoltButton({
  children = "View all",
  hoverLabel,
  href,
  onClick,
  icon = "arrow",
  active = false,
  colors = {},
  className = "",
  ...rest
}) {
  const gridRef = useRef(null);
  const timerRef = useRef(0);
  const palette = colors.palette || DEFAULT_PALETTE;

  // grille de pixels qui clignote pendant le survol
  useEffect(() => {
    const grid = gridRef.current;
    if (!grid) return;
    const root = grid.closest(".vb");
    const cells = [];
    for (let i = 0; i < 36; i++) {
      const c = document.createElement("span");
      c.style.display = "block";
      cells.push(c);
      grid.appendChild(c);
    }
    const flick = () => {
      cells.forEach((c) => {
        c.style.background =
          Math.random() < 0.5 ? palette[Math.floor(Math.random() * palette.length)] : "transparent";
      });
    };
    const start = () => {
      flick();
      timerRef.current = setInterval(flick, 90);
    };
    const stop = () => clearInterval(timerRef.current);
    root.addEventListener("mouseenter", start);
    root.addEventListener("mouseleave", stop);
    return () => {
      stop();
      root.removeEventListener("mouseenter", start);
      root.removeEventListener("mouseleave", stop);
      cells.forEach((c) => c.remove());
    };
  }, [palette]);

  const vars = Object.fromEntries(
    Object.entries({
      "--vb-text": colors.text,
      "--vb-frame": colors.frame,
      "--vb-border": colors.border,
    }).filter(([, v]) => v)
  );

  const Tag = href ? "a" : "button";

  return (
    <Tag
      className={`vb ${className}`}
      style={vars}
      data-active={active}
      {...(href ? { href } : { type: "button" })}
      onClick={onClick}
      {...rest}
    >
      <style>{CSS}</style>
      <em className="vb-halo" />
      <span className="vb-frame">
        <span className="vb-grid" ref={gridRef} />
      </span>
      <span className="vb-content">
        <strong className="vb-label">
          <span data-hover={hoverLabel || children}>
            <i>{children}</i>
          </span>
        </strong>
        {icon && (
          <span className="vb-ic">
            <span><Icon kind={icon} /></span>
            <span><Icon kind={icon} /></span>
          </span>
        )}
      </span>
    </Tag>
  );
}

