function Carousel({ orientation = "horizontal", opts, setApi, plugins, className, children, ...props }) {
  const [carouselRef, api] = useEmblaCarousel({ ...opts, axis: orientation === "horizontal" ? "x" : "y" }, plugins)
  const [canScrollPrev, setCanScrollPrev] = React.useState(false)
  const [canScrollNext, setCanScrollNext] = React.useState(false)

  const onSelect = React.useCallback((api) => {
    if (!api) return
    setCanScrollPrev(api.canScrollPrev())
    setCanScrollNext(api.canScrollNext())
  }, [])

  const scrollPrev = React.useCallback(() => api?.scrollPrev(), [api])
  const scrollNext = React.useCallback(() => api?.scrollNext(), [api])

  const handleKeyDown = React.useCallback((event) => {
    if (event.key === "ArrowLeft") { event.preventDefault(); scrollPrev() }
    else if (event.key === "ArrowRight") { event.preventDefault(); scrollNext() }
  }, [scrollPrev, scrollNext])

  React.useEffect(() => {
    if (!api || !setApi) return
    setApi(api)
  }, [api, setApi])

  React.useEffect(() => {
    if (!api) return
    onSelect(api)
    api.on("reInit", onSelect)
    api.on("select", onSelect)
    return () => api?.off("select", onSelect)
  }, [api, onSelect])

  return (
    <CarouselContext.Provider value={{ carouselRef, api, opts, orientation: orientation || (opts?.axis === "y" ? "vertical" : "horizontal"), scrollPrev, scrollNext, canScrollPrev, canScrollNext }}>
      <div onKeyDownCapture={handleKeyDown} className={cn("relative", className)} role="region" aria-roledescription="carousel" data-slot="carousel" {...props}>
        {children}
      </div>
    </CarouselContext.Provider>
  )
}

function CarouselContent({ className, ...props }) {
  const { carouselRef, orientation } = useCarousel()
  return (
    <div ref={carouselRef} className="overflow-hidden" data-slot="carousel-content">
      <div className={cn("flex", orientation === "horizontal" ? "-ml-4" : "-mt-4 flex-col", className)} {...props} />
    </div>
  )
}

function CarouselItem({ className, ...props }) {
  const { orientation } = useCarousel()
  return (
    <div role="group" aria-roledescription="slide" data-slot="carousel-item" className={cn("min-w-0 shrink-0 grow-0 basis-full", orientation === "horizontal" ? "pl-4" : "pt-4", className)} {...props} />
  )
}

function CarouselPrevious({ className, variant = "outline", size = "icon-sm", ...props }) {
  const { orientation, scrollPrev, canScrollPrev } = useCarousel()
  return (
    <button data-slot="carousel-previous" disabled={!canScrollPrev} onClick={scrollPrev} className={cn("group/button inline-flex shrink-0 items-center justify-center rounded-lg border border-border bg-background hover:bg-muted h-7 rounded-[min(var(--radius-md),12px)] px-2.5 absolute touch-manipulation rounded-full", orientation === "horizontal" ? "top-1/2 -left-12 -translate-y-1/2" : "-top-12 left-1/2 -translate-x-1/2 rotate-90", className)} {...props}>
      <ChevronLeftIcon />
      <span className="sr-only">Previous slide</span>
    </button>
  )
}

function CarouselNext({ className, variant = "outline", size = "icon-sm", ...props }) {
  const { orientation, scrollNext, canScrollNext } = useCarousel()
  return (
    <button data-slot="carousel-next" disabled={!canScrollNext} onClick={scrollNext} className={cn("group/button inline-flex shrink-0 items-center justify-center rounded-lg border border-border bg-background hover:bg-muted h-7 rounded-[min(var(--radius-md),12px)] px-2.5 absolute touch-manipulation rounded-full", orientation === "horizontal" ? "top-1/2 -right-12 -translate-y-1/2" : "-bottom-12 left-1/2 -translate-x-1/2 rotate-90", className)} {...props}>
      <ChevronRightIcon />
      <span className="sr-only">Next slide</span>
    </button>
  )
}

