  },
  {
    label: "Job Enquiries",
    lines: [{ text: "jobs@meridian.studio", href: "mailto:jobs@meridian.studio" }],
  },
  {
    label: "Freelancer & Collaborator Enquiries",
    lines: [{ text: "collab@meridian.studio", href: "mailto:collab@meridian.studio" }],
  },
  { label: "Telephone", lines: ["+44 (0) 20 0000 0000"] },
  {
