      { text: "LinkedIn", href: "https://www.linkedin.com", external: true },
    ],
  },
];

/* petits glyphes maison — le central en pioche un autre à chaque
   franchissement de ligne (équivalent de leur set d'icônes) */
const GLYPHS = [
  // astérisque 8 branches
  (key) => (
    <svg key={key} viewBox="0 0 64 64" fill="currentColor" className="h-full w-full">
      {[0, 45, 90, 135, 180, 225, 270, 315].map((a) => (
        <path key={a} d="M32 2 L36 27 L32 32 L28 27 Z" transform={`rotate(${a} 32 32)`} />
