      {[0, 90, 180, 270].map((a) => (
        <ellipse key={a} cx="32" cy="15" rx="9" ry="14" transform={`rotate(${a} 32 32)`} />
      ))}
      <circle cx="32" cy="32" r="5" />
    </svg>
  ),
  // étoile 4 pointes (sparkle)
  (key) => (
    <svg key={key} viewBox="0 0 64 64" fill="currentColor" className="h-full w-full">
      <path d="M32 2 C34 20 36 22 30 32 C36 42 34 44 32 62 C30 44 28 42 34 32 C28 22 30 20 32 2 Z" transform="rotate(45 32 32)" />
      <path d="M32 2 C36 22 42 28 62 32 C42 36 36 42 32 62 C28 42 22 36 2 32 C22 28 28 22 32 2 Z" />
    </svg>
  ),
  // anneau épais
  (key) => (
    <svg key={key} viewBox="0 0 64 64" fill="none" stroke="currentColor" strokeWidth="11" className="h-full w-full">
      <circle cx="32" cy="32" r="22" />
    </svg>
  ),
  // losange évidé
  (key) => (
    <svg key={key} viewBox="0 0 64 64" fill="currentColor" className="h-full w-full">
      <path d="M32 2 L62 32 L32 62 L2 32 Z M32 20 L44 32 L32 44 L20 32 Z" fillRule="evenodd" />
    </svg>
  ),
  // demi-cercles opposés
  (key) => (
    <svg key={key} viewBox="0 0 64 64" fill="currentColor" className="h-full w-full">
      <path d="M4 30 A28 28 0 0 1 60 30 Z" />
      <path d="M60 34 A28 28 0 0 1 4 34 Z" transform="rotate(0 32 32)" />
    </svg>
  ),
];

function Clock({ timeZone = "Europe/London", suffix = "(GMT)" }) {
  const [time, setTime] = useState("");
  useEffect(() => {
    const fmt = new Intl.DateTimeFormat("en-GB", {
      timeZone,
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    });
    const tick = () => setTime(fmt.format(new Date()));
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, [timeZone]);
  return (
    <span className="tabular-nums">
      {time} {suffix}
    </span>
  );
}

function Rows({ items }) {
  // chaque groupe = 1 ligne avec libellé + N lignes de valeurs
  const rows = items.flatMap((item) =>
    (item.clock ? [{ clock: true }] : item.lines).map((line, i) => ({
      label: i === 0 ? item.label : "",
      line,
      clock: item.clock,
    }))
  );
  return (
    <div className="flex flex-col gap-[5px]">
      {rows.map((r, i) => (
        <div key={i} className="cti-row flex gap-4 text-[13px] leading-[1.4] md:gap-5 md:text-[14px]">
          <div className="cti-cell-l flex-1 text-right text-black">{r.label}</div>
          <div className="cti-cell-r flex-1 text-[#AFAEA7]">
            {r.clock ? (
              <Clock />
            ) : typeof r.line === "string" ? (
              r.line
            ) : (
              <a
                className="transition-colors hover:text-black hover:underline hover:underline-offset-[3px] focus-visible:text-black"
                href={r.line.href}
                {...(r.line.external ? { target: "_blank", rel: "noreferrer" } : {})}
              >
                {r.line.text}
              </a>
            )}
          </div>
        </div>
      ))}
    </div>
  );
}

export default function ContactInfinite({
  items = DEFAULT_ITEMS,
  footerLeft = "A Creative Studio",
  footerRight = { text: "Watch Showreel", href: "#" },
  className = "",
}) {
  const root = useRef(null);
  const copies = useRef([]);
  const glyphRefs = useRef([]);

  useGSAP(
    () => {
      const el = root.current;
      const els = copies.current.filter(Boolean);
      if (!el || !els.length) return;

      const gaps = gsap.utils.toArray(".cti-gap", el);
      const rows = gsap.utils.toArray(".cti-row", el);
      const glyphs = glyphRefs.current.filter(Boolean);
      const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
      // l'écartement des colonnes ne joue que sur desktop avec pointeur précis
      const desktopFine = window.matchMedia(
        "(min-width: 992px) and (any-hover: hover) and (any-pointer: fine)"
      );

      let copyH = 0;
      let frameH = -1;
      let scrollTarget = 0;
      let scrollCur = 0;
      let lastScrollTime = 0;
      let glyphIndex = 0;

      const showGlyph = (i) => {
        glyphs.forEach((s, j) => (s.style.display = j === i ? "block" : "none"));
      };
      showGlyph(0);

      const swapGlyph = () => {
        if (glyphs.length < 2) return;
        let next = Math.floor(Math.random() * glyphs.length);
        if (next === glyphIndex) next = (next + 1) % glyphs.length;
        glyphIndex = next;
        showGlyph(next);
      };

      // position "au repos" : la liste de la 1re copie centrée dans le cadre
      const home = () => {
        const h = el.clientHeight;
        const gapH = h * 0.8;
        return gapH + (copyH - gapH) / 2 - h / 2;
      };

      // l'air entre deux répétitions = 80% de la hauteur du cadre
      const measure = () => {
        const h = el.clientHeight;
        gaps.forEach((g) => (g.style.height = `${h * 0.8}px`));
        const newH = els[0].offsetHeight;
        if (newH !== copyH) {
          copyH = newH;
          scrollTarget = home();
          if (reduced) scrollCur = scrollTarget;
        }
      };
      measure();
      frameH = el.clientHeight;
      if (!reduced) scrollCur = scrollTarget + frameH * 0.5; // la liste glisse en place à l'arrivée

      /* signature : les 2 colonnes d'une ligne s'écartent (smoothstep,
         max 5rem chacune) à l'approche du glyphe central fixe ; à chaque
         franchissement du centre, le glyphe change de forme */
      const updateSplit = () => {
        if (!desktopFine.matches) return;
        const frame = el.getBoundingClientRect();
        const centerY = frame.top + frame.height / 2;
        rows.forEach((row) => {
          const r = row.getBoundingClientRect();
          if (r.bottom < frame.top - 100 || r.top > frame.bottom + 100) {
            row._centered = false;
            return;
          }
          const dist = Math.abs(r.top + r.height / 2 - centerY);
          const maxDist = (MARK_SIZE + r.height) * 1.5;
          let p = Math.max(0, 1 - dist / maxDist);
          p = p * p * (3 - 2 * p); // smoothstep
          gsap.set(row.children[0], { marginRight: `${p * SPLIT_MAX_REM}rem` });
          gsap.set(row.children[1], { marginLeft: `${p * SPLIT_MAX_REM}rem` });
          if (p > 0.8) {
            if (!row._centered) {
              row._centered = true;
              swapGlyph();
            }
          } else {
            row._centered = false;
          }
        });
      };

      const render = () => {
        // auto-réparation : re-mesure dès que la hauteur du cadre change
        const h = el.clientHeight;
        if (h !== frameH) {
          frameH = h;
          measure();
        }
        if (!copyH) return;
        scrollCur += (scrollTarget - scrollCur) * LERP;
        const wrap = gsap.utils.wrap(-copyH, copyH * 2);
        els.forEach((c, i) => gsap.set(c, { y: wrap(i * copyH - scrollCur) }));
        updateSplit();
      };
      render();

      if (reduced) {
        scrollCur = scrollTarget;
        render();
        return;
      }

      gsap.ticker.add(render);

      // molette : clampée à ±50px par cran, au plus un cran par 16ms
      const consumeTick = () => {
        const now = Date.now();
        if (now - lastScrollTime < SCROLL_COOLDOWN_MS) return false;
        lastScrollTime = now;
        return true;
      };
      const onWheel = (e) => {
        e.preventDefault();
        if (!consumeTick()) return;
        scrollTarget += gsap.utils.clamp(-MAX_SCROLL_DELTA, MAX_SCROLL_DELTA, e.deltaY);
      };

      let touching = false;
      let touchY = 0;
      const onTouchStart = (e) => {
        touching = true;
        if (e.touches?.length) touchY = e.touches[0].clientY;
        lastScrollTime = 0;
      };
      const onTouchMove = (e) => {
        e.preventDefault();
        if (!touching || !consumeTick() || !e.touches?.length) return;
        const y = e.touches[0].clientY;
        scrollTarget += gsap.utils.clamp(
          -MAX_SCROLL_DELTA,
          MAX_SCROLL_DELTA,
          (touchY - y) * TOUCH_MULTIPLIER
        );
        touchY = y;
      };
      const onTouchEnd = () => {
        touching = false;
        lastScrollTime = 0;
      };

      el.addEventListener("wheel", onWheel, { passive: false });
      el.addEventListener("touchstart", onTouchStart, { passive: true });
      el.addEventListener("touchmove", onTouchMove, { passive: false });
      el.addEventListener("touchend", onTouchEnd, { passive: true });

      const onResize = () => {
        frameH = el.clientHeight;
        measure();
      };
      window.addEventListener("resize", onResize);

      gsap.from(rows, { opacity: 0, duration: 0.9, stagger: 0.02, ease: "power2.out" });

      return () => {
        gsap.ticker.remove(render);
        el.removeEventListener("wheel", onWheel);
        el.removeEventListener("touchstart", onTouchStart);
        el.removeEventListener("touchmove", onTouchMove);
        el.removeEventListener("touchend", onTouchEnd);
        window.removeEventListener("resize", onResize);
      };
    },
    { scope: root }
  );

  return (
    <section
      ref={root}
      className={`absolute inset-0 select-none overflow-hidden bg-white text-black ${className}`}
      style={{ touchAction: "none", overscrollBehavior: "none" }}
    >
      <h2 className="sr-only">Contact</h2>

      {[0, 1, 2].map((i) => (
        <div
          key={i}
          ref={(c) => (copies.current[i] = c)}
          aria-hidden={i > 0}
          className="absolute left-0 top-0 w-full will-change-transform"
        >
          {/* l'air entre deux répétitions de la liste */}
          <div className="cti-gap" />
          <Rows items={items} />
        </div>
      ))}

      {/* glyphe fixe au centre du cadre — les lignes s'ouvrent autour de lui */}
      <div
        className="pointer-events-none absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 text-black"
        style={{ width: MARK_SIZE, height: MARK_SIZE }}
        aria-hidden="true"
      >
        {GLYPHS.map((make, i) => (
          <div
            key={i}
            ref={(c) => (glyphRefs.current[i] = c)}
            className="absolute inset-0"
            style={{ display: i === 0 ? "block" : "none" }}
          >
            {make(i)}
          </div>
        ))}
      </div>

      <div className="pointer-events-none absolute bottom-0 left-0 right-0 z-[2] flex items-center justify-between px-4 py-4 text-[11px] uppercase tracking-[0.05em] md:px-8">
        <span className="pointer-events-auto">{footerLeft}</span>
        <a
          className="pointer-events-auto hover:underline hover:underline-offset-[3px]"
          href={footerRight.href}
        >
          {footerRight.text}
        </a>
      </div>
    </section>
  );
}

