import React from "react";
import { File, Search, Settings } from "lucide-react";

function cn(...classes) {
  return classes.filter(Boolean).join(" ");
}

function OrbitingCircles({
  className,
  children,
  reverse,
  duration = 20,
  radius = 160,
  path = true,
  iconSize = 30,
  speed = 1,
  ...props
}) {
  const calculatedDuration = duration / speed;
  const direction = reverse ? -1 : 1;

  return (
    <div className="absolute inset-0 flex items-center justify-center">
      <style>{`
        @keyframes orbit-${direction} {
          0% {
            transform: rotate(calc(var(--angle) * 1deg)) translateY(calc(var(--radius) * 1px)) rotate(calc(var(--angle) * -1deg));
          }
          100% {
            transform: rotate(calc(var(--angle) * 1deg + 360deg * ${direction})) translateY(calc(var(--radius) * 1px)) rotate(calc(var(--angle) * -1deg - 360deg * ${direction}));
          }
        }
        .animate-orbit-${direction} {
          animation: orbit-${direction} calc(var(--duration) * 1s) linear infinite;
        }
      `}</style>
      {path && (
        <svg
          xmlns="http://www.w3.org/2000/svg"
          version="1.1"
          className="pointer-events-none absolute inset-0 size-full">
          <circle
            className="stroke-black/10 stroke-1 dark:stroke-white/10"
            cx="50%"
            cy="50%"
            r={radius}
            fill="none" />
        </svg>
      )}
      {React.Children.map(children, (child, index) => {
        const angle = (360 / React.Children.count(children)) * index;
        return (
          <div
            className={cn(
              `animate-orbit-${direction} absolute flex size-(--icon-size) transform-gpu items-center justify-center rounded-full`,
              className
            )}
            style={{
              "--duration": calculatedDuration,
              "--radius": radius,
              "--angle": angle,
              "--icon-size": `${iconSize}px`,
              top: `calc(50% - ${iconSize / 2}px)`,
              left: `calc(50% - ${iconSize / 2}px)`,
            }}
            {...props}>
            {child}
          </div>
        );
      })}
    </div>
  );
}

