function MenubarMenu({ open, defaultOpen = false, onOpenChange, children, ...props }) {
  const [internalOpen, setInternalOpen] = React.useState(defaultOpen)
  const isOpen = open !== undefined ? open : internalOpen
  const setOpen = React.useCallback((value) => {
    const newOpen = typeof value === "function" ? value(isOpen) : value
    if (onOpenChange) onOpenChange(newOpen)
    else setInternalOpen(newOpen)
  }, [isOpen, onOpenChange])

  return (
    <div data-slot="menubar-menu" data-state={isOpen ? "open" : "closed"} {...props}>
      {React.Children.map(children, (child) => {
        if (React.isValidElement(child)) return React.cloneElement(child, { _open: isOpen, _setOpen: setOpen })
        return child
      })}
    </div>
  )
}

function MenubarTrigger({ className, children, _open, _setOpen, ...props }) {
  if (!React.isValidElement(children)) return children
  return React.cloneElement(children, {
    onClick: (e) => { if (children.props?.onClick) children.props.onClick(e); _setOpen(!(_open ?? false)) },
    className: cn("flex items-center rounded-sm px-1.5 py-[2px] text-sm font-medium outline-hidden select-none hover:bg-muted aria-expanded:bg-muted", className),
    "data-slot": "menubar-trigger",
    "aria-expanded": _open,
    ...props,
  })
}

function MenubarContent({ className, align = "start", alignOffset = -4, sideOffset = 8, children, _open, _setOpen, ...props }) {
  const contentRef = React.useRef(null)
  const [position, setPosition] = React.useState({ top: 0, left: 0 })

  React.useEffect(() => {
    if (!_open) return
    const trigger = contentRef.current?.closest('[data-slot="menubar-menu"]')?.querySelector('[data-slot="menubar-trigger"]')
    if (trigger) {
      const rect = trigger.getBoundingClientRect()
      setPosition({ top: rect.bottom + sideOffset, left: rect.left + alignOffset })
    }
  }, [_open, sideOffset, alignOffset])

  React.useEffect(() => {
    if (!_open) return
    const handleClickOutside = (e) => { if (contentRef.current && !contentRef.current.contains(e.target)) _setOpen?.(false) }
    document.addEventListener("mousedown", handleClickOutside)
    return () => document.removeEventListener("mousedown", handleClickOutside)
  }, [_open, _setOpen])

  if (!_open) return null

  return (
    <div ref={contentRef} data-slot="menubar-content" className={cn("fixed z-50 min-w-36 overflow-hidden rounded-lg bg-popover p-1 text-popover-foreground shadow-md ring-1 ring-foreground/10", className)} style={{ top: `${position.top}px`, left: `${position.left}px` }} {...props}>
      {children}
    </div>
  )
}

function MenubarItem({ className, inset, variant = "default", children, onSelect, ...props }) {
  return (
    <div data-slot="menubar-item" data-inset={inset || undefined} data-variant={variant} className={cn("group/menubar-item relative flex cursor-default items-center gap-1.5 rounded-md px-1.5 py-1 text-sm outline-hidden select-none focus:bg-accent focus:text-accent-foreground data-inset:pl-7 data-[variant=destructive]:text-destructive data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0", className)} onClick={(e) => { onSelect?.(); props.onClick?.(e) }} {...props}>
      {children}
    </div>
  )
}

function MenubarCheckboxItem({ className, children, checked, inset, onCheckedChange, ...props }) {
  return (
    <MenubarItem data-slot="menubar-checkbox-item" data-inset={inset || undefined} className={cn("relative flex cursor-default items-center gap-1.5 rounded-md py-1 pr-1.5 pl-7 text-sm outline-hidden select-none focus:bg-accent focus:text-accent-foreground data-inset:pl-7 data-disabled:pointer-events-none", className)} onSelect={() => onCheckedChange?.(!checked)} {...props}>
      <span className="pointer-events-none absolute left-1.5 flex size-4 items-center justify-center">{checked && <CheckIcon />}</span>
      {children}
    </MenubarItem>
  )
}

function MenubarRadioItem({ className, children, inset, checked, ...props }) {
  return (
    <MenubarItem data-slot="menubar-radio-item" data-inset={inset || undefined} className={cn("relative flex cursor-default items-center gap-1.5 rounded-md py-1 pr-1.5 pl-7 text-sm outline-hidden select-none focus:bg-accent focus:text-accent-foreground data-inset:pl-7 data-disabled:pointer-events-none data-disabled:opacity-50", className)} {...props}>
      <span className="pointer-events-none absolute left-1.5 flex size-4 items-center justify-center">{checked && <CheckIcon />}</span>
      {children}
    </MenubarItem>
  )
}

function MenubarRadioGroup({ value, onValueChange, children, ...props }) {
  return (
    <div data-slot="menubar-radio-group" {...props}>
      {React.Children.map(children, (child) => {
        if (React.isValidElement(child)) return React.cloneElement(child, { checked: child.props?.value === value, onSelect: () => onValueChange?.(child.props?.value) })
        return child
      })}
    </div>
  )
}

function MenubarLabel({ className, inset, children, ...props }) {
  return <div data-slot="menubar-label" data-inset={inset || undefined} className={cn("px-1.5 py-1 text-sm font-medium data-inset:pl-7", className)} {...props}>{children}</div>
}

function MenubarSeparator({ className, ...props }) {
  return <div data-slot="menubar-separator" className={cn("-mx-1 my-1 h-px bg-border", className)} {...props} />
}

function MenubarShortcut({ className, ...props }) {
  return <span data-slot="menubar-shortcut" className={cn("ml-auto text-xs tracking-widest text-muted-foreground", className)} {...props} />
}

function MenubarGroup({ children, ...props }) {
  return <div data-slot="menubar-group" {...props}>{children}</div>
}

function MenubarSub({ open, defaultOpen = false, onOpenChange, children, ...props }) {
  const [internalOpen, setInternalOpen] = React.useState(defaultOpen)
  const isOpen = open !== undefined ? open : internalOpen
  return (
    <div data-slot="menubar-sub" data-state={isOpen ? "open" : "closed"} {...props}>
      {React.Children.map(children, (child) => {
        if (React.isValidElement(child)) return React.cloneElement(child, { _subOpen: isOpen, _subSetOpen: setInternalOpen })
        return child
      })}
    </div>
  )
}

function MenubarSubTrigger({ className, inset, children, _subOpen, _subSetOpen, ...props }) {
  return (
    <MenubarItem data-slot="menubar-sub-trigger" data-inset={inset || undefined} className={cn("flex cursor-default items-center gap-1.5 rounded-md px-1.5 py-1 text-sm outline-none select-none focus:bg-accent focus:text-accent-foreground data-inset:pl-7 data-open:bg-accent data-open:text-accent-foreground", className)} onSelect={() => _subSetOpen?.(!(_subOpen ?? false))} {...props}>
      {children}
      <ChevronRightIcon className="ml-auto size-4" />
    </MenubarItem>
  )
}

function MenubarSubContent({ className, children, _subOpen, ...props }) {
  if (!_subOpen) return null
  return (
    <div data-slot="menubar-sub-content" className={cn("absolute z-50 min-w-32 overflow-hidden rounded-lg bg-popover p-1 text-popover-foreground shadow-lg ring-1 ring-foreground/10", className)} {...props}>
      {children}
    </div>
  )
}

