  Usage :
      import PopprMenu from "./poppr-menu";
      <PopprMenu />   // se fixe au viewport (position: fixed)

  Props (toutes optionnelles) :
    logo      texte du logo                      (déf. "studio")
    links     [{ label, href, count? }]
