/* anneau de 1px pour le sweep du CTA (pill ext. − pill int., evenodd) */
function ringPath(w, h) {
  const r = h / 2;
  const r2 = r - 1;
  return [
    `M ${r} 0 H ${w - r} A ${r} ${r} 0 0 1 ${w - r} ${h} H ${r} A ${r} ${r} 0 0 1 ${r} 0 Z`,
    `M ${r} 1 H ${w - r} A ${r2} ${r2} 0 0 1 ${w - r} ${h - 1} H ${r} A ${r2} ${r2} 0 0 1 ${r} 1 Z`,
  ].join(" ");
}

function SweepCta({ text, href }) {
  const ref = useRef(null);
  const [dims, setDims] = useState({ w: 0, h: 0 });
  const clipId = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const measure = () => {
      const w = el.offsetWidth;
      const h = el.offsetHeight;
      setDims((d) => (d.w === w && d.h === h ? d : { w, h }));
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  const { w, h } = dims;
  const cp = { pathLength: 1, cx: w / 2, cy: h / 2, r: w / 2, strokeWidth: w };

  return (
    <a ref={ref} className="pm-cta" href={href}>
      <span className="pm-cta-inner">
        <span className="pm-cta-t -static">{text}</span>
        <span className="pm-cta-t -hover" aria-hidden="true">{text}</span>
      </span>
      {w > 0 && (
        <svg className="pm-cta-svg" viewBox={`0 0 ${w} ${h}`} aria-hidden="true">
          <defs>
            <clipPath id={`pmcta-${clipId}`}>
              <path d={ringPath(w, h)} fillRule="evenodd" clipRule="evenodd" />
            </clipPath>
          </defs>
          <g clipPath={`url(#pmcta-${clipId})`}>
            <g className="pm-cta-circles">
              <g className="pm-cta-circles-o">
                <circle className="pm-cta-c -base" {...cp} />
                <circle className="pm-cta-c -l2" {...cp} />
                <circle className="pm-cta-c -l3" {...cp} />
                <circle className="pm-cta-c -l4" {...cp} />
              </g>
              <circle className="pm-cta-c -hover" {...cp} />
            </g>
          </g>
        </svg>
      )}
    </a>
  );
}

function Letters({ word, layer, baseDelay }) {
  return (
    <span className={`pm-letters -${layer}`} aria-hidden={layer === "top"}>
      {word.split("").map((ch, i) => (
        <span
          key={i}
          className="pm-letter"
          style={{
            "--d": `${baseDelay + i * 0.03 + (layer === "top" ? 0.05 : 0)}s`,
            "--i": i,
          }}
        >
          {ch}
        </span>
      ))}
    </span>
  );
}

export default function PopprMenu({
  logo = "studio",
  links = DEFAULT_LINKS,
  contact = DEFAULT_CONTACT,
  cta = { text: "Get in touch", href: "#contact" },
  colors = {},
  onNavigate,
  defaultOpen = false,
  className = "",
}) {
  const [open, setOpen] = useState(defaultOpen);
  const [mounted, setMounted] = useState(defaultOpen);
  const pathRef = useRef(null);
  const rafRef = useRef(0);

  const maskId = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  /* bord d'attaque courbe : le contrôle central traîne derrière les bords */
  const animateCurve = (opening) => {
    const path = pathRef.current;
    if (!path) return;
    cancelAnimationFrame(rafRef.current);

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const setD = (edge, ctrl) =>
      path.setAttribute("d", `M 1 ${edge} Q 0.5 ${ctrl} 0 ${edge} L 0 1 L 1 1 Z`);

    if (reduced) {
      setD(opening ? 0 : 1, opening ? 0 : 1);
      if (!opening) setMounted(false);
      return;
    }

    const DUR = 1000;
    const start = performance.now();
    const frame = (now) => {
      const t = Math.min(1, (now - start) / DUR);
      const ease = 1 - Math.pow(1 - t, 5); // quintOut
      const p = opening ? ease : 1 - ease; // taux d'ouverture
      const edge = 1 - p;
      const bulge = Math.sin(t * Math.PI) * 0.12 * (opening ? 1 : -1);
      setD(edge, Math.min(1.2, Math.max(-0.2, edge + bulge)));
      if (t < 1) rafRef.current = requestAnimationFrame(frame);
      else if (!opening) setMounted(false);
    };
    rafRef.current = requestAnimationFrame(frame);
  };

  const openMenu = () => {
    setMounted(true);
    setOpen(true);
    animateCurve(true);
  };
  const closeMenu = () => {
    setOpen(false);
    animateCurve(false);
  };

  // Échap + verrou du scroll
  useEffect(() => {
    if (!open) return;
    const onKey = (e) => e.key === "Escape" && closeMenu();
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    window.addEventListener("keydown", onKey);
    return () => {
      document.body.style.overflow = prev;
      window.removeEventListener("keydown", onKey);
    };
  }, [open]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => () => cancelAnimationFrame(rafRef.current), []);

  const onLink = (e, href) => {
    if (onNavigate) {
      e.preventDefault();
      closeMenu();
      onNavigate(href);
    }
  };

  const vars = Object.fromEntries(
    Object.entries({
      "--pm-bg": colors.bg,
      "--pm-fg": colors.fg,
      "--pm-overlay": colors.overlay,
      "--pm-overlay-text": colors.overlayText,
      "--pm-accent": colors.accent,
      "--pm-turquoise": colors.turquoise,
      "--pm-yellow": colors.yellow,
      "--pm-count-bg": colors.countBg,
    }).filter(([, v]) => v)
  );

  return (
    <nav className={`pm ${className}`} style={vars} data-open={open} data-mounted={mounted}>
      <style>{CSS}</style>

      {/* clipPath du rideau (coordonnées normalisées 0..1) */}
      <svg width="0" height="0" style={{ position: "absolute" }} aria-hidden="true">
        <defs>
          <clipPath id={`pm-mask-${maskId}`} clipPathUnits="objectBoundingBox">
            <path
              ref={pathRef}
              d={defaultOpen ? "M 1 0 Q 0.5 0 0 0 L 0 1 L 1 1 Z" : "M 1 1 Q 0.5 1 0 1 L 0 1 L 1 1 Z"}
            />
          </clipPath>
        </defs>
      </svg>

      {/* barre fermée */}
      <div className="pm-bar">
        <a className="pm-logo" href="#" onClick={(e) => onLink(e, "/")}>
          {logo.split("").map((ch, i) => (
            <span key={i}>{ch}</span>
          ))}
        </a>
        <div className="pm-bar-right">
          <SweepCta text={cta.text} href={cta.href} />
          <button
            className="pm-round"
            aria-label="Ouvrir le menu"
            aria-expanded={open}
