`;

export default function VoltMenu({
  logo = "VOLT",
  groups = DEFAULT_GROUPS,
  colors = {},
  onNavigate,
  defaultOpen = false,
  className = "",
}) {
  const [open, setOpen] = useState(defaultOpen);
  const gridRef = useRef(null);
  const timerRef = useRef(0);

  // grille de pixels du bouton — clignote pendant le survol
  useEffect(() => {
    const grid = gridRef.current;
    if (!grid) return;
    const btn = grid.closest(".vm-btn");
    const cells = [];
    for (let i = 0; i < 36; i++) {
      const c = document.createElement("span");
      c.style.display = "block";
      cells.push(c);
      grid.appendChild(c);
    }
    const flick = () => {
      cells.forEach((c) => {
        c.style.background =
          Math.random() < 0.5 ? PALETTE[Math.floor(Math.random() * PALETTE.length)] : "transparent";
      });
    };
    const start = () => {
      flick();
      timerRef.current = setInterval(flick, 90);
    };
    const stop = () => clearInterval(timerRef.current);
    btn.addEventListener("mouseenter", start);
    btn.addEventListener("mouseleave", stop);
    return () => {
      stop();
      btn.removeEventListener("mouseenter", start);
      btn.removeEventListener("mouseleave", stop);
      cells.forEach((c) => c.remove());
    };
  }, []);

  // Échap + verrou du scroll
  useEffect(() => {
    if (!open) return;
    const onKey = (e) => e.key === "Escape" && setOpen(false);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    window.addEventListener("keydown", onKey);
    return () => {
      document.body.style.overflow = prev;
      window.removeEventListener("keydown", onKey);
    };
  }, [open]);

  const onLink = (e, href) => {
    if (onNavigate) {
      e.preventDefault();
      setOpen(false);
      onNavigate(href);
    }
  };

  const vars = Object.fromEntries(
    Object.entries({
      "--vm-panel": colors.panel,
      "--vm-panel-text": colors.panelText,
      "--vm-panel-mobile": colors.panelMobile,
    }).filter(([, v]) => v)
  );

  return (
    <nav className={`vm ${className}`} style={vars} data-open={open}>
      <style>{CSS}</style>

      <div className="vm-overlay" onClick={() => setOpen(false)} aria-hidden="true" />

      <div className="vm-bar">
        <a className="vm-logo" href="#" onClick={(e) => onLink(e, "/")}>
          {logo}
        </a>
        <button
          className="vm-btn"
          aria-expanded={open}
          aria-label={open ? "Fermer le menu" : "Ouvrir le menu"}
          onClick={() => setOpen((v) => !v)}
        >
          <em className="vm-btn-halo" />
          <span className="vm-btn-frame">
            <span className="vm-btn-grid" ref={gridRef} />
          </span>
          <span className="vm-btn-content">
            <strong className="vm-btn-label">
              <span data-hover="CLOSE">
                <i>MENU</i>
              </span>
            </strong>
            <span className="vm-btn-ic">
              <svg width="13" height="13" viewBox="0 0 13 13" fill="none" aria-hidden="true">
                <line x1="6.5" y1="1" x2="6.5" y2="12" stroke="currentColor" strokeWidth="1.5" />
                <line x1="1" y1="6.5" x2="12" y2="6.5" stroke="currentColor" strokeWidth="1.5" />
              </svg>
            </span>
          </span>
        </button>
      </div>

      <div className="vm-panel-wrap">
        <div className="vm-panel">
          <ul className="vm-ul">
            {groups.map((g) => (
              <li key={g.label}>
                {g.href ? (
                  <a className="vm-group-label" href={g.href} onClick={(e) => onLink(e, g.href)}>
                    {g.label}
                  </a>
                ) : (
                  <span className="vm-group-label">{g.label}</span>
                )}
                {g.children && (
                  <ul className="vm-sub">
                    {g.children.map((c) => (
                      <li key={c.label}>
                        <a href={c.href} onClick={(e) => onLink(e, c.href)}>
                          {c.label}
                        </a>
                      </li>
                    ))}
                  </ul>
                )}
              </li>
            ))}
          </ul>
        </div>
      </div>
    </nav>
  );
}

