function MediaFallback({ hue, ratio = "3/4" }) {
  return (
    <div
      className="dt-talent-fallback"
      style={{
        background: `
          radial-gradient(120% 130% at 20% 10%, hsl(${hue} 70% 60% / 0.55), transparent 55%),
          radial-gradient(140% 140% at 85% 90%, hsl(${(hue + 40) % 360} 80% 45% / 0.55), transparent 55%),
          #111
        `,
      }}
    />
  );
}

export default function DetroitHomeTemplate({
  brand = "atelier",
  nav = null,
  navLinks = {
    left: ["Talents", "Projects"],
    right: ["Services", "Insights", "Contact"],
  },
  book = {
    title: "Our recent essay",
    line: "A placeholder note on process and craft",
  },
  hero = DEFAULT_HERO,
  talents = DEFAULT_TALENTS,
  projects = DEFAULT_PROJECTS,
  services = DEFAULT_SERVICES,
  insights = DEFAULT_INSIGHTS,
  footer = DEFAULT_FOOTER,
  className = "",
}) {
  const root = useRef(null);
  const talentsRef = useRef(null);
  const [reduced, setReduced] = useState(false);
  const [bookOpen, setBookOpen] = useState(true);
  const cleanupFns = useRef([]);

  useEffect(() => {
    setReduced(window.matchMedia("(prefers-reduced-motion: reduce)").matches);
    return () => { cleanupFns.current.forEach((fn) => fn()); cleanupFns.current = []; };
  }, []);

  useGSAP(
    () => {
      const el = root.current;
      const isReduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
      if (isReduced) return;

      // révélation caractère par caractère du hero
      gsap.utils.toArray(".dt-line-inner", el).forEach((line) => {
        gsap.from(line.querySelectorAll(".dt-char"), {
          yPercent: 105,
          rotate: 3,
          duration: 1.1,
          ease: "expo.out",
          stagger: 0.02,
          scrollTrigger: { trigger: line, start: "top 92%" },
        });
      });

      // fade-up des blocs
      gsap.utils.toArray("[data-dt-animate]", el).forEach((node) => {
        gsap.to(node, {
          opacity: 1,
          y: 0,
          duration: 0.9,
          ease: "expo.out",
          delay: (parseFloat(node.dataset.dtAnimate) || 0) / 1000,
          scrollTrigger: { trigger: node, start: "top 90%" },
        });
      });

      // ─── Talents : tapis roulant scroll-driven ───────────────────
      // Modèle "slots à largeur variable" : N slots pré-calculés, chaque
      // slot k a une scale prédéfinie qui croît de 0.30 (slot 0, gauche)
      // à 1.40 (slot N-1, droite) via un smoothstep. Les slots sont
      // COLLÉS par construction (chaque slot commence là où le précédent
      // finit, cumulativement). Chaque carte i occupe un slot fractionnaire
      // (i + travel) mod N ; travel est piloté par le scroll, lissé par un
      // lerp sur gsap.ticker.  Aucun espace ne peut apparaître entre les
      // cartes : la position d'un item est toujours calculée par le cumul
      // des largeurs scale-based des slots précédents.
      const rail = talentsRef.current;
      const wrap = rail?.closest(".dt-talents-scroller");
      const items = rail ? [...rail.querySelectorAll(".dt-talent")] : [];
      if (rail && wrap && items.length) {
        const N = items.length;
        const laps = 2.4;               // tours complets pendant le scroll
        const scaleMin = 0.30;          // slot 0 : plus petit
        const scaleMax = 1.40;          // slot N-1 : plus grand
        const smoothstep = (x) => x * x * (3 - 2 * x);
        const scaleOfSlot = (k) => scaleMin + smoothstep(gsap.utils.clamp(0, 1, k / (N - 1))) * (scaleMax - scaleMin);

        let vw = window.innerWidth;
        let itemW = items[0].offsetWidth;
        const cumX = new Array(N + 1);  // cumX[k] = position x du bord gauche du slot k

        const layout = () => {
          vw = window.innerWidth;
          itemW = items[0].offsetWidth;
          cumX[0] = 0;
          for (let k = 0; k < N; k++) {
            cumX[k + 1] = cumX[k] + itemW * scaleOfSlot(k);
          }
        };
        layout();

        const render = () => {
          const travel = state.rendered * N * laps;
          for (let i = 0; i < N; i++) {
            // slot fractionnaire de la carte i (wrap dans [0, N))
            const raw = i + travel;
            const p = ((raw % N) + N) % N;
            const k = Math.floor(p);
            const frac = p - k;
            const s0 = scaleOfSlot(k);
            const s1 = scaleOfSlot((k + 1) % N);
            // interpolation entre le slot k et k+1 (le prochain slot est plus grand,
            // donc la scale croît continûment quand la carte glisse vers la droite)
            const nextS = (k + 1) < N ? s1 : s0; // évite la chute abrupte au wrap
            const scale = s0 * (1 - frac) + nextS * frac;
            // x = bord gauche du slot k + fraction × largeur du slot k
            const x = cumX[k] + itemW * s0 * frac;
            // opacité : fade-in rapide sur les 0.4 premiers slots (naissance
            // bas-gauche), pas de fade-out (la sortie droite se fait naturellement
            // hors écran car beltLen > vw)
            const opacity = gsap.utils.clamp(0, 1, p / 0.4);
            const el = items[i];
            el.style.transform = `translate3d(${x}px, 0, 0) scale(${scale})`;
            el.style.opacity = opacity;
          }
        };

        // Lissage : target suit ScrollTrigger, rendered rattrape avec lerp .09
        const state = { target: 0, rendered: 0 };
        const tick = () => {
          state.rendered += (state.target - state.rendered) * 0.09;
          if (Math.abs(state.target - state.rendered) < 1e-5) state.rendered = state.target;
          render();
        };
        gsap.ticker.add(tick);
        cleanupFns.current.push(() => gsap.ticker.remove(tick));

        render();

        const st = ScrollTrigger.create({
          trigger: wrap,
          start: "top top",
          end: "bottom bottom",
          onUpdate: (self) => { state.target = self.progress; },
          invalidateOnRefresh: true,
        });

        const onResize = () => { layout(); render(); };
        window.addEventListener("resize", onResize);

        cleanupFns.current.push(() => {
          st.kill();
          window.removeEventListener("resize", onResize);
        });
      }
    },
    { scope: root }
  );

  return (
    <div className={`dt ${reduced ? "dt-reduced" : ""} ${className}`} ref={root}>
      <style>{CSS}</style>

      {nav || (
        <header className="dt-nav">
          <div className="dt-nav-l">
            <a href="#" className="dt-nav-logo" aria-label={brand}><BrandMark /></a>
            {navLinks.left.map((l) => (
              <a key={l} href={`#${l.toLowerCase()}`} className="dt-caps">{l}</a>
            ))}
          </div>
          <div className="dt-nav-r">
            {navLinks.right.map((l) => (
              <a key={l} href={`#${l.toLowerCase()}`} className="dt-caps">{l}</a>
            ))}
          </div>
        </header>
      )}

      {book && bookOpen && (
        <aside className="dt-book" role="complementary">
          <div className="dt-book-thumb">{brand[0]?.toUpperCase()}</div>
          <div>
            <div className="dt-book-title">{book.title}</div>
            <div>{book.line}</div>
          </div>
          <button className="dt-book-close" onClick={() => setBookOpen(false)} aria-label="Fermer">
            <svg width="10" height="10" viewBox="0 0 10 10" aria-hidden="true">
              <path d="M1 1 L9 9 M9 1 L1 9" stroke="currentColor" strokeWidth="1.5" />
            </svg>
          </button>
        </aside>
      )}

      {/* HERO */}
      <section className="dt-hero" id="hero">
        <SplitLines lines={hero.lines} />
        <p className="dt-hero-caption" data-dt-animate="200">
          <span className="dt-hl">{brand.toUpperCase()}</span> — {hero.caption}
        </p>
        <div className="dt-hero-cats" data-dt-animate="300">{hero.cats}</div>
      </section>

      {/* TALENTS — tapis roulant scroll-driven (naissance bas-gauche,
          grandeur en glissant vers la droite, disparition puis boucle) */}
      <div className="dt-talents-scroller" id="talents">
        <section className="dt-talents" ref={talentsRef} aria-label="Talents">
          <div className="dt-talents-inner">
            {talents.items.map((t, i) => (
              <a key={i} className="dt-talent" href={t.href || "#"}>
                <span className="dt-talent-tag-wrap">
                  <span className="dt-tag dt-talent-tag">{t.tag}</span>
                </span>
                <div className="dt-talent-media">
                  {t.image ? <img src={t.image} alt={t.name} /> : <MediaFallback hue={t.hue ?? 200} />}
                  <span className="dt-talent-name">{t.name}</span>
                </div>
              </a>
            ))}
          </div>
        </section>
      </div>

      {/* PROJECTS */}
      <section className="dt-projects" id="projects">
        <div className="dt-section-head">
          <h2 className="dt-caps" data-dt-animate>{projects.label}</h2>
