function useAudio(enabled) {
  const ctxRef = useRef(null);
  const bufferRef = useRef(null);
  const readyRef = useRef(false);

  useEffect(() => {
    if (!enabled) return;
    const init = async () => {
      try {
        ctxRef.current = new AudioContext();
        const res = await fetch("/sounds/sound.ogg");
        if (!res.ok) return;
        bufferRef.current = await ctxRef.current.decodeAudioData(await res.arrayBuffer());
        readyRef.current = true;
      } catch {}
    };
    init();
    return () => { ctxRef.current?.close(); };
  }, [enabled]);

  const playSound = (sound) => {
    if (!readyRef.current || !ctxRef.current || !bufferRef.current || !sound) return;
    if (ctxRef.current.state === "suspended") ctxRef.current.resume();
    const src = ctxRef.current.createBufferSource();
    src.buffer = bufferRef.current;
    src.connect(ctxRef.current.destination);
    src.start(0, sound[0] / 1000, sound[1] / 1000);
  };

  const down = (key) => playSound(KEY_SOUNDS_DOWN[key.toUpperCase()] || KEY_SOUNDS_DOWN[key]);
  const up = (key) => playSound(KEY_SOUNDS_UP[key.toUpperCase()] || KEY_SOUNDS_UP[key]);
  return { down, up };
}

const tokenColors = {
  command: "text-emerald-400", flag: "text-sky-400", string: "text-amber-300", number: "text-purple-400", operator: "text-red-400", path: "text-cyan-300", variable: "text-pink-400", comment: "text-neutral-500", default: "text-neutral-300",
};

function tokenizeBash(text) {
  const tokens = [];
  const words = text.split(/(\s+)/);
  let isFirstWord = true;
  for (const word of words) {
    if (/^\s+$/.test(word)) { tokens.push({ type: "default", value: word }); continue; }
    if (word.startsWith("#")) { tokens.push({ type: "comment", value: word }); continue; }
    if (word.startsWith("$")) { tokens.push({ type: "variable", value: word }); isFirstWord = false; continue; }
    if (word.startsWith("--") || word.startsWith("-")) { tokens.push({ type: "flag", value: word }); isFirstWord = false; continue; }
    if (/^["'].*["']$/.test(word)) { tokens.push({ type: "string", value: word }); isFirstWord = false; continue; }
    if (/^\d+$/.test(word)) { tokens.push({ type: "number", value: word }); isFirstWord = false; continue; }
    if (/^[|>&<]+$/.test(word)) { tokens.push({ type: "operator", value: word }); isFirstWord = true; continue; }
    if (word.includes("/") || word.startsWith(".") || word.startsWith("~")) { tokens.push({ type: "path", value: word }); isFirstWord = false; continue; }
    if (isFirstWord) { tokens.push({ type: "command", value: word }); isFirstWord = false; continue; }
    tokens.push({ type: "default", value: word });
  }
  return tokens;
}

function SyntaxHighlightedText({ text }) {
  const tokens = tokenizeBash(text);
  return <>{tokens.map((token, i) => (<span key={i} className={tokenColors[token.type]}>{token.value}</span>))}</>;
}

export function TerminalSimple({
  commands = ["npx shadcn@latest init"],
  outputs = {},
  username = "Manus-Macbook",
  className,
  typingSpeed = 50,
  delayBetweenCommands = 800,
  initialDelay = 500,
  enableSound = true,
}) {
  const containerRef = useRef(null);
  const contentRef = useRef(null);
  const { down, up } = useAudio(enableSound);

  const [lines, setLines] = useState([]);
  const [currentText, setCurrentText] = useState("");
  const [commandIdx, setCommandIdx] = useState(0);
  const [charIdx, setCharIdx] = useState(0);
  const [outputIdx, setOutputIdx] = useState(-1);
  const [phase, setPhase] = useState("idle");
  const [cursorVisible, setCursorVisible] = useState(true);
  const [inView, setInView] = useState(false);

  const currentCommand = commands[commandIdx] || "";
  const currentOutputs = outputs[commandIdx] || [];
  const isLastCommand = commandIdx === commands.length - 1;

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) setInView(true);
    }, { threshold: 0.1 });
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (!inView || phase !== "idle") return;
    const t = setTimeout(() => setPhase("typing"), initialDelay);
    return () => clearTimeout(t);
  }, [inView, phase, initialDelay]);

  useEffect(() => {
    if (phase !== "typing") return;
    if (charIdx < currentCommand.length) {
      const char = currentCommand[charIdx];
      down(char);
      const t = setTimeout(() => {
        up(char);
        setCurrentText(currentCommand.slice(0, charIdx + 1));
        setCharIdx((c) => c + 1);
      }, typingSpeed + Math.random() * 30);
      return () => clearTimeout(t);
    } else {
      down("Enter");
      const t = setTimeout(() => { up("Enter"); setPhase("executing"); }, 80);
      return () => clearTimeout(t);
    }
  }, [phase, charIdx, currentCommand, typingSpeed, down, up]);

  useEffect(() => {
    if (phase !== "executing") return;
    setLines((prev) => [...prev, { type: "command", content: currentCommand }]);
    setCurrentText("");
    if (currentOutputs.length > 0) { setOutputIdx(0); setPhase("outputting"); }
    else if (isLastCommand) { setPhase("done"); }
    else { setPhase("pausing"); }
  }, [phase, currentCommand, currentOutputs.length, isLastCommand]);

  useEffect(() => {
    if (phase !== "outputting") return;
    if (outputIdx >= 0 && outputIdx < currentOutputs.length) {
      const t = setTimeout(() => {
        setLines((prev) => [...prev, { type: "output", content: currentOutputs[outputIdx] }]);
        setOutputIdx((i) => i + 1);
      }, 150);
      return () => clearTimeout(t);
    } else if (outputIdx >= currentOutputs.length) {
      const t = setTimeout(() => { if (isLastCommand) { setPhase("done"); } else { setPhase("pausing"); } }, 300);
      return () => clearTimeout(t);
    }
  }, [phase, outputIdx, currentOutputs, isLastCommand]);

  useEffect(() => {
    if (phase !== "pausing") return;
    const t = setTimeout(() => { setCharIdx(0); setOutputIdx(-1); setCommandIdx((c) => c + 1); setPhase("typing"); }, delayBetweenCommands);
    return () => clearTimeout(t);
  }, [phase, delayBetweenCommands]);

  useEffect(() => {
    const interval = setInterval(() => setCursorVisible((v) => !v), 530);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (contentRef.current) contentRef.current.scrollTop = contentRef.current.scrollHeight;
  }, [lines, phase]);

  const prompt = (
    <span className="text-neutral-500">
      <span className="text-sky-500">{username}</span>
      <span className="text-emerald-600">:</span>
      <span className="text-sky-400">~</span>
      <span className="text-neutral-500">$</span>{" "}
    </span>
  );

  return (
    <div ref={containerRef} className={cn("mx-auto w-full max-w-xl px-4 font-mono text-xs", className)}>
      <div className="overflow-hidden rounded-lg border border-neutral-800 bg-neutral-900 shadow-2xl">
        <div className="flex items-center gap-2 bg-neutral-800 px-4 py-3">
          <div className="flex items-center gap-1.5">
            <div className="h-3 w-3 rounded-full bg-red-500 transition-colors hover:bg-red-600" />
            <div className="h-3 w-3 rounded-full bg-yellow-500 transition-colors hover:bg-yellow-600" />
            <div className="h-3 w-3 rounded-full bg-green-500 transition-colors hover:bg-green-600" />
          </div>
          <div className="flex-1 text-center">
            <span className="truncate text-xs text-neutral-400">{username} — bash</span>
          </div>
          <div className="w-[52px]" />
        </div>
        <div ref={contentRef} className="no-visible-scrollbar h-80 overflow-y-auto p-4 font-mono text-left">
          {lines.map((line, i) => (
            <div key={i} className="leading-relaxed whitespace-pre-wrap">
              {line.type === "command" ? (
                <span>{prompt}<SyntaxHighlightedText text={line.content} /></span>
              ) : line.type === "output" ? (
                <span className="text-emerald-400">{line.content}</span>
              ) : (
                <span className="text-neutral-400">{line.content}</span>
              )}
            </div>
          ))}
          {phase === "typing" && (
            <div className="leading-relaxed whitespace-pre-wrap">
              {prompt}<SyntaxHighlightedText text={currentText} />
              <span className="ml-0.5 inline-block h-4 w-2 bg-neutral-300 align-middle" />
            </div>
          )}
          {(phase === "done" || phase === "pausing" || phase === "outputting") && (
            <div className="leading-relaxed whitespace-pre-wrap">
              {prompt}
              <span className={cn("inline-block h-4 w-2 bg-neutral-300 align-middle transition-opacity duration-100", !cursorVisible && "opacity-0")} />
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

