import * as React from "react"
import { cn } from "@/lib/utils"

function Collapsible({
  open,
  defaultOpen = false,
  onOpenChange,
  disabled,
  children,
  ...props
}) {
  const [internalOpen, setInternalOpen] = React.useState(defaultOpen)
  const isOpen = open !== undefined ? open : internalOpen

  const setOpen = React.useCallback((value) => {
    const newOpen = typeof value === "function" ? value(isOpen) : value
    if (onOpenChange) {
      onOpenChange(newOpen)
    } else {
      setInternalOpen(newOpen)
    }
  }, [isOpen, onOpenChange])

  return (
    <div
      data-slot="collapsible"
      data-state={isOpen ? "open" : "closed"}
      data-disabled={disabled || undefined}
      {...props}
    >
      {React.Children.map(children, (child) => {
        if (React.isValidElement(child)) {
          return React.cloneElement(child, {
            _open: isOpen,
            _setOpen: setOpen,
            _disabled: disabled,
          })
        }
        return child
      })}
    </div>
  )
}

function CollapsibleTrigger({ children, _open, _setOpen, _disabled, ...props }) {
  return React.cloneElement(React.Children.only(children), {
    onClick: (e) => {
      if (children.props?.onClick) children.props.onClick(e)
      if (!_disabled) _setOpen(!(_open ?? false))
    },
    ...props,
  })
}

function CollapsibleContent({ children, _open, ...props }) {
  return (
    <div
      data-slot="collapsible-content"
      data-state={_open ? "open" : "closed"}
      className={cn(
        "overflow-hidden transition-all data-[state=closed]:animate-collapsible-up data-[state=open]:animate-collapsible-down",
        props.className
      )}
      {...props}
    >
      {_open && children}
    </div>
  )
}

export { Collapsible, CollapsibleTrigger, CollapsibleContent }

