function DropdownMenu({
  open,
  defaultOpen = false,
  onOpenChange,
  children,
  ...props
}) {
  const [internalOpen, setInternalOpen] = React.useState(defaultOpen)
  const isOpen = open !== undefined ? open : internalOpen
  const triggerRef = React.useRef(null)

  const setOpen = React.useCallback((value) => {
    const newOpen = typeof value === "function" ? value(isOpen) : value
    if (onOpenChange) {
      onOpenChange(newOpen)
    } else {
      setInternalOpen(newOpen)
    }
  }, [isOpen, onOpenChange])

  return (
    <div data-slot="dropdown-menu" data-state={isOpen ? "open" : "closed"} {...props}>
      {React.Children.map(children, (child) => {
        if (React.isValidElement(child)) {
          return React.cloneElement(child, {
            _open: isOpen,
            _setOpen: setOpen,
            _triggerRef: triggerRef,
          })
        }
        return child
      })}
    </div>
  )
}

function DropdownMenuTrigger({ children, _open, _setOpen, _triggerRef, ...props }) {
  if (!React.isValidElement(children)) return children
  return React.cloneElement(children, {
    ref: _triggerRef,
    onClick: (e) => {
      if (children.props?.onClick) children.props.onClick(e)
      _setOpen(!(_open ?? false))
    },
    ...props,
  })
}

function DropdownMenuContent({
  className,
  align = "start",
  sideOffset = 4,
  children,
  _open,
  _setOpen,
  _triggerRef,
  ...props
}) {
  const contentRef = React.useRef(null)
  const [position, setPosition] = React.useState({ top: 0, left: 0 })

  React.useEffect(() => {
    if (!_open || !_triggerRef?.current) return

    const rect = _triggerRef.current.getBoundingClientRect()
    const alignOffset = align === "start" ? 0 : align === "end" ? -rect.width + rect.width : -rect.width / 2

    setPosition({
      top: rect.bottom + sideOffset,
      left: rect.left + alignOffset,
    })
  }, [_open, align, sideOffset, _triggerRef])

  React.useEffect(() => {
    if (!_open) return

    const handleClickOutside = (e) => {
      if (contentRef.current && !contentRef.current.contains(e.target)) {
        _setOpen(false)
      }
    }
    const handleEscape = (e) => {
      if (e.key === "Escape") _setOpen(false)
    }
    document.addEventListener("mousedown", handleClickOutside)
    document.addEventListener("keydown", handleEscape)
    return () => {
      document.removeEventListener("mousedown", handleClickOutside)
      document.removeEventListener("keydown", handleEscape)
    }
  }, [_open, _setOpen])

  if (!_open) return null

  return (
    <div
      ref={contentRef}
      data-slot="dropdown-menu-content"
      className={cn(
        "fixed z-50 min-w-32 max-h-96 overflow-auto rounded-lg bg-popover p-1 text-popover-foreground shadow-md ring-1 ring-foreground/10",
        className
      )}
      style={{ top: `${position.top}px`, left: `${position.left}px` }}
      {...props}
    >
      {children}
    </div>
  )
}

function DropdownMenuGroup({ children, ...props }) {
