function MenubarMenu({
  open,
  defaultOpen = false,
  onOpenChange,
  children,
  ...props
}) {
  const [internalOpen, setInternalOpen] = React.useState(defaultOpen)
  const isOpen = open !== undefined ? open : internalOpen

  const setOpen = React.useCallback((value) => {
    const newOpen = typeof value === "function" ? value(isOpen) : value
    if (onOpenChange) {
      onOpenChange(newOpen)
    } else {
      setInternalOpen(newOpen)
    }
  }, [isOpen, onOpenChange])

  return (
    <div data-slot="menubar-menu" data-state={isOpen ? "open" : "closed"} {...props}>
      {React.Children.map(children, (child) => {
        if (React.isValidElement(child)) {
          return React.cloneElement(child, {
            _open: isOpen,
            _setOpen: setOpen,
          })
        }
        return child
      })}
    </div>
  )
}

function MenubarTrigger({ className, children, _open, _setOpen, ...props }) {
  if (!React.isValidElement(children)) return children
  return React.cloneElement(children, {
    onClick: (e) => {
      if (children.props?.onClick) children.props.onClick(e)
      _setOpen(!(_open ?? false))
    },
    className: cn(
      "flex items-center rounded-sm px-1.5 py-[2px] text-sm font-medium outline-hidden select-none hover:bg-muted aria-expanded:bg-muted",
      className
    ),
    "data-slot": "menubar-trigger",
    "aria-expanded": _open,
    ...props,
  })
}

function MenubarContent({
  className,
  align = "start",
  alignOffset = -4,
  sideOffset = 8,
  children,
  _open,
  ...props
}) {
  const contentRef = React.useRef(null)
  const [position, setPosition] = React.useState({ top: 0, left: 0 })

  React.useEffect(() => {
    if (!_open) return
    const trigger = contentRef.current?.closest('[data-slot="menubar-menu"]')?.querySelector('[data-slot="menubar-trigger"]')
    if (trigger) {
      const rect = trigger.getBoundingClientRect()
      setPosition({
        top: rect.bottom + sideOffset,
        left: rect.left + alignOffset,
      })
    }
  }, [_open, sideOffset, alignOffset])

  React.useEffect(() => {
    if (!_open) return
    const handleClickOutside = (e) => {
      if (contentRef.current && !contentRef.current.contains(e.target)) {
        _setOpen?.(false)
      }
    }
    document.addEventListener("mousedown", handleClickOutside)
    return () => document.removeEventListener("mousedown", handleClickOutside)
  }, [_open, _setOpen])

  if (!_open) return null

  return (
    <div
      ref={contentRef}
      data-slot="menubar-content"
      className={cn(
        "fixed z-50 min-w-36 overflow-hidden rounded-lg bg-popover p-1 text-popover-foreground shadow-md ring-1 ring-foreground/10",
        className
      )}
      style={{ top: `${position.top}px`, left: `${position.left}px` }}
      {...props}
    >
      {children}
    </div>
  )
}

