      })}
    </>
  );
}

import * as React from "react"
import { cn } from "@/lib/utils"

function Popover({
  open,
  defaultOpen = false,
  onOpenChange,
  children,
  ...props
}) {
  const [internalOpen, setInternalOpen] = React.useState(defaultOpen)
  const isOpen = open !== undefined ? open : internalOpen

  const setOpen = React.useCallback((value) => {
    const newOpen = typeof value === "function" ? value(isOpen) : value
    if (onOpenChange) {
      onOpenChange(newOpen)
    } else {
      setInternalOpen(newOpen)
    }
  }, [isOpen, onOpenChange])

  return (
    <div data-slot="popover" data-state={isOpen ? "open" : "closed"} {...props}>
      {React.Children.map(children, (child) => {
        if (React.isValidElement(child)) {
          return React.cloneElement(child, {
            _open: isOpen,
            _setOpen: setOpen,
          })
        }
        return child
      })}
    </div>
  )
}

function PopoverTrigger({ children, _open, _setOpen, ...props }) {
  if (!React.isValidElement(children)) return children

  return React.cloneElement(children, {
    onClick: (e) => {
      if (children.props?.onClick) children.props.onClick(e)
      _setOpen(!(_open ?? false))
    },
    ...props,
  })
}

function PopoverContent({
  className,
  align = "center",
  sideOffset = 4,
  children,
  _open,
  ...props
}) {
  const contentRef = React.useRef(null)

  React.useEffect(() => {
    if (!_open) return

    const handleClickOutside = (e) => {
      if (contentRef.current && !contentRef.current.contains(e.target)) {
        const trigger = contentRef.current.closest('[data-slot="popover"]')?.querySelector('[data-slot="popover-trigger"]')
        if (trigger) trigger.click()
      }
    }
    document.addEventListener("mousedown", handleClickOutside)
    return () => document.removeEventListener("mousedown", handleClickOutside)
  }, [_open])

  if (!_open) return null

  const alignClasses = {
    start: "left-0",
    center: "left-1/2 -translate-x-1/2",
    end: "right-0",
  }

  return (
    <div
      ref={contentRef}
      data-slot="popover-content"
      className={cn(
        "absolute z-50 flex w-72 flex-col gap-2.5 rounded-lg bg-popover p-2.5 text-sm text-popover-foreground shadow-md ring-1 ring-foreground/10",
        alignClasses[align],
        className
      )}
      style={{ top: `${sideOffset}px` }}
      {...props}
    >
      {children}
    </div>
  )
}

function PopoverAnchor({ children, ...props }) {
  return (
    <div data-slot="popover-anchor" {...props}>
      {children}
    </div>
  )
}

function PopoverHeader({ className, ...props }) {
  return (
