import * as React from "react"
import { cn } from "@/lib/utils"

function Slider({
  className,
  defaultValue,
  value,
  min = 0,
  max = 100,
  step = 1,
  onValueChange,
  disabled,
  orientation = "horizontal",
  ...props
}) {
  const _values = React.useMemo(() =>
    Array.isArray(value)
      ? value
      : Array.isArray(defaultValue)
        ? defaultValue
        : [min, max], [value, defaultValue, min, max])

  const [internalValues, setInternalValues] = React.useState(_values)
  const [draggingIndex, setDraggingIndex] = React.useState(null)
  const trackRef = React.useRef(null)

  const values = value !== undefined ? value : internalValues

  const getPercentage = (val) => ((val - min) / (max - min)) * 100

  const getValueFromPosition = (pos) => {
    const rect = trackRef.current.getBoundingClientRect()
    const isVertical = orientation === "vertical"
    const length = isVertical ? rect.height : rect.width
    const offset = isVertical ? pos - rect.top : pos - rect.left
    const ratio = Math.min(Math.max(offset / length, 0), 1)
    return Math.round((ratio * (max - min) + min) / step) * step
  }

  const handlePointerDown = (index) => (e) => {
    e.preventDefault()
    setDraggingIndex(index)
  }

  React.useEffect(() => {
    if (draggingIndex === null) return

    const handlePointerMove = (e) => {
      const newVal = getValueFromPosition(e.clientY || e.clientX)
      const newValues = [...values]
      newValues[draggingIndex] = newVal
      if (value === undefined) setInternalValues(newValues)
      onValueChange?.(newValues)
    }

    const handlePointerUp = () => {
      setDraggingIndex(null)
    }

    window.addEventListener("pointermove", handlePointerMove)
    window.addEventListener("pointerup", handlePointerUp)
    return () => {
      window.removeEventListener("pointermove", handlePointerMove)
      window.removeEventListener("pointerup", handlePointerUp)
    }
  }, [draggingIndex, values, value, onValueChange, min, max, step, orientation])

  return (
    <div
      data-slot="slider"
      data-disabled={disabled || undefined}
      data-orientation={orientation}
      className={cn(
        "relative flex w-full touch-none items-center select-none data-[disabled]:opacity-50 data-[orientation=vertical]:h-full data-[orientation=vertical]:min-h-40 data-[orientation=vertical]:w-auto data-[orientation=vertical]:flex-col",
        className
      )}
      {...props}
    >
      <div
        ref={trackRef}
        data-slot="slider-track"
        data-orientation={orientation}
        className={cn(
          "relative grow overflow-hidden rounded-full bg-muted",
          orientation === "horizontal" ? "h-1 w-full" : "h-full w-1"
        )}
      >
        <div
          data-slot="slider-range"
          className={cn(
            "absolute bg-primary select-none",
            orientation === "horizontal"
              ? `h-full left-0`
              : `w-full bottom-0`,
          )}
          style={
            orientation === "horizontal"
              ? {
                  left: `${getPercentage(values[0])}%`,
                  width: `${getPercentage(values[values.length - 1]) - getPercentage(values[0])}%`,
                }
              : {
                  bottom: `${getPercentage(values[0])}%`,
                  height: `${getPercentage(values[values.length - 1]) - getPercentage(values[0])}%`,
                }
          }
        />
      </div>
      {values.map((val, index) => (
        <div
          data-slot="slider-thumb"
          key={index}
          className={cn(
            "absolute size-3 shrink-0 rounded-full border border-ring bg-white ring-ring/50 transition-[color,box-shadow] select-none cursor-pointer hover:ring-3 focus-visible:ring-3 focus-visible:outline-hidden active:ring-3 disabled:pointer-events-none disabled:opacity-50",
            orientation === "horizontal"
              ? "top-1/2 -translate-y-1/2"
              : "left-1/2 -translate-x-1/2"
          )}
          style={
            orientation === "horizontal"
              ? { left: `${getPercentage(val)}%`, transform: "translate(-50%, -50%)" }
              : { bottom: `${getPercentage(val)}%`, transform: "translate(-50%, 50%)" }
          }
          onPointerDown={handlePointerDown(index)}
          tabIndex={0}
          role="slider"
          aria-valuemin={min}
          aria-valuemax={max}
          aria-valuenow={val}
        />
      ))}
    </div>
  )
}

export { Slider }

