import * as React from "react"
import { cn } from "@/lib/utils"

function TooltipProvider({
  delayDuration = 0,
  children,
  ...props
}) {
  return (
    <div data-slot="tooltip-provider" data-delay={delayDuration} {...props}>
      {children}
    </div>
  )
}

function Tooltip({
  open,
  defaultOpen = false,
  delayDuration = 0,
  onOpenChange,
  children,
  ...props
}) {
  const [internalOpen, setInternalOpen] = React.useState(defaultOpen)
  const [delayedOpen, setDelayedOpen] = React.useState(false)
  const isOpen = open !== undefined ? open : delayedOpen

  React.useEffect(() => {
    if (!internalOpen) {
      setDelayedOpen(false)
      return
    }
    const timer = setTimeout(() => setDelayedOpen(true), delayDuration)
    return () => clearTimeout(timer)
  }, [internalOpen, delayDuration])

  return (
    <div data-slot="tooltip" data-state={isOpen ? "open" : "closed"} {...props}>
      {React.Children.map(children, (child) => {
        if (React.isValidElement(child)) {
          return React.cloneElement(child, {
            _open: isOpen,
            _setOpen: setInternalOpen,
          })
        }
        return child
      })}
    </div>
  )
}

function TooltipTrigger({ children, _open, _setOpen, ...props }) {
  if (!React.isValidElement(children)) return children

  return React.cloneElement(children, {
    onMouseEnter: (e) => {
      if (children.props?.onMouseEnter) children.props.onMouseEnter(e)
      _setOpen(true)
    },
    onMouseLeave: (e) => {
      if (children.props?.onMouseLeave) children.props.onMouseLeave(e)
      _setOpen(false)
    },
    onFocus: (e) => {
      if (children.props?.onFocus) children.props.onFocus(e)
      _setOpen(true)
    },
    onBlur: (e) => {
      if (children.props?.onBlur) children.props.onBlur(e)
      _setOpen(false)
    },
    ...props,
  })
}

function TooltipContent({
  className,
  sideOffset = 0,
  children,
  _open,
  side = "top",
  ...props
}) {
  if (!_open) return null

  const sideClasses = {
    top: "bottom-full left-1/2 -translate-x-1/2 mb-2",
    bottom: "top-full left-1/2 -translate-x-1/2 mt-2",
    left: "right-full top-1/2 -translate-y-1/2 mr-2",
    right: "left-full top-1/2 -translate-y-1/2 ml-2",
  }

  return (
    <div
      data-slot="tooltip-content"
      className={cn(
        "absolute z-50 inline-flex w-fit max-w-xs items-center gap-1.5 rounded-md bg-foreground px-3 py-1.5 text-xs text-background",
        sideClasses[side],
        className
      )}
      style={{ marginBottom: sideOffset || undefined, marginTop: sideOffset || undefined }}
      {...props}
    >
      {children}
    </div>
  )
}

export { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger }

