/* bouton à éclosion (double texte + 3 disques) */
function BloomButton({ text, href, className = "" }) {
  return (
    <a className={`pp-btn ${className}`} href={href}>
      <span className="pp-btn-bg">
        <span className="pp-btn-layers">
          <span className="pp-btn-layer -l1" />
          <span className="pp-btn-layer -l2" />
          <span className="pp-btn-layer -l3" />
        </span>
      </span>
      <span className="pp-btn-inner">
        <span className="pp-btn-t -static">{text}</span>
        <span className="pp-btn-t -hover" aria-hidden="true">{text}</span>
      </span>
    </a>
  );
}

/* titre découpé en lignes masquées + caractères (révélé par GSAP) */
function SplitLines({ lines, className = "" }) {
  return (
    <h2 className={`pp-title-lg ${className}`}>
      {lines.map((line, li) => (
        <span className="pp-line" key={li} aria-label={line}>
          <span className="pp-line-inner" style={{ display: "block" }}>
            {line.split("").map((ch, ci) => (
              <span className="pp-char" aria-hidden="true" key={ci}>
                {ch === " " ? " " : ch}
              </span>
            ))}
          </span>
        </span>
      ))}
    </h2>
  );
}

/* dégradé placeholder par teinte, remplacé par item.image si fournie */
function CardMedia({ item }) {
  return (
    <div className="pp-card-img">
      {item.image ? (
        <img src={item.image} alt="" draggable="false" />
      ) : (
        <div
          className="pp-media-fallback"
          style={{
            background: `radial-gradient(100% 130% at 20% 10%, hsl(${item.hue ?? 260} 80% 62% / .5), transparent 60%),
                         radial-gradient(120% 140% at 85% 90%, hsl(${(item.hue ?? 260) + 60} 85% 60% / .35), transparent 55%),
                         #101012`,
            position: "absolute",
            inset: 0,
          }}
        />
      )}
    </div>
  );
}

export default function PopprHomeTemplate({
  brand = "studio",
  nav = null,
  hero = DEFAULT_HERO,
  work = DEFAULT_WORK,
  insights = DEFAULT_INSIGHTS,
  cta = DEFAULT_CTA,
  footer = DEFAULT_FOOTER,
  className = "",
}) {
  const root = useRef(null);
  const glowRef = useRef(null);
  const ringRef = useRef(null);
  const cursorRef = useRef(null);
  const carouselRef = useRef(null);
  const logoRef = useRef(null);
  const [reduced, setReduced] = useState(false);

  // registre de nettoyages impératifs (listeners/tickers hors contexte gsap)
  const cleanupFns = useRef([]).current;
  useEffect(() => () => { cleanupFns.forEach((fn) => fn()); cleanupFns.length = 0; }, [cleanupFns]);

  useEffect(() => {
    setReduced(window.matchMedia("(prefers-reduced-motion: reduce)").matches);
  }, []);

  useGSAP(
    () => {
      const isReduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

      /* ----- fond ambiant : couleurs par section ----- */
      const palette = {
        purple: COLORS.purple,
        yellow: COLORS.yellow,
        turquoise: COLORS.turquoise,
        black: "#000000",
      };
      const glow = glowRef.current;
      gsap.utils.toArray("[data-colors]", root.current).forEach((sec) => {
        const [one, two, op] = sec.dataset.colors.split(",");
        ScrollTrigger.create({
          trigger: sec,
          start: "top 55%",
          end: "bottom 55%",
          onToggle: (self) => {
            if (self.isActive && glow) {
              glow.style.setProperty("--pp-glow-one", palette[one] || one);
              glow.style.setProperty("--pp-glow-two", palette[two] || two);
              glow.style.setProperty("--pp-glow-opacity", op || "0.4");
            }
          },
        });
      });

      if (isReduced) return; // fond ok, mais pas d'animations

      /* ----- fade-up des blocs ----- */
      gsap.utils.toArray("[data-pp-animate]", root.current).forEach((el) => {
        gsap.to(el, {
          opacity: 1,
          y: 0,
          duration: 1.1,
          ease: "expo.out",
          delay: (parseFloat(el.dataset.ppAnimate) || 0) / 1000,
          scrollTrigger: { trigger: el, start: "top 88%" },
        });
      });

      /* ----- révélation caractère par caractère ----- */
      gsap.utils.toArray(".pp-line-inner", root.current).forEach((line) => {
        gsap.from(line.querySelectorAll(".pp-char"), {
          yPercent: 110,
          rotate: 4,
          duration: 1.1,
          ease: "expo.out",
          stagger: 0.025,
          scrollTrigger: { trigger: line, start: "top 92%" },
        });
      });

      /* ----- parallaxe + pan du média hero ----- */
      const media = root.current.querySelector(".pp-hero-media");
      const mediaInner = root.current.querySelector(".pp-hero-media-inner");
      if (media && mediaInner) {
        gsap.to(media, {
          yPercent: -12,
          ease: "none",
          scrollTrigger: { trigger: media, start: "top bottom", end: "bottom top", scrub: true },
        });
        const onMove = (e) => {
          const nx = e.clientX / window.innerWidth - 0.5;
          const ny = e.clientY / window.innerHeight - 0.5;
          gsap.to(mediaInner, { x: nx * -24, y: ny * -18, duration: 1.2, ease: "power2.out" });
        };
        window.addEventListener("mousemove", onMove);
        cleanupFns.push(() => window.removeEventListener("mousemove", onMove));
      }

      /* ----- logo : lettres écrasées par la vélocité du scroll ----- */
      const letters = logoRef.current ? [...logoRef.current.children] : [];
      let lastY = window.scrollY;
      let vel = 0;
      const onLogoTick = () => {
        const y = window.scrollY;
        vel += (gsap.utils.clamp(-30, 30, y - lastY) - vel) * 0.12;
        lastY = y;
        letters.forEach((l, i) => {
          gsap.set(l, {
            y: Math.abs(vel) * -0.15,
            scaleY: 1 - Math.min(0.35, Math.abs(vel) * 0.012),
            rotation: vel * 0.12 * (i % 2 === 0 ? 1 : -1) * 0.5,
          });
        });
      };
      if (letters.length) gsap.ticker.add(onLogoTick);
      cleanupFns.push(() => gsap.ticker.remove(onLogoTick));

      /* ----- carrousel cylindrique draggable à l'inertie ----- */
      const ring = ringRef.current;
      const zone = carouselRef.current;
      const cursor = cursorRef.current;
      if (ring && zone) {
        const state = { rot: 0, vel: 0.03, dragging: false, lastX: 0 };
        const onTick = () => {
          if (!state.dragging) {
            state.rot += state.vel;
            state.vel += (0.03 - state.vel) * 0.03; // retour à la dérive lente
          }
          gsap.set(ring, { rotationY: state.rot });
        };
        gsap.ticker.add(onTick);
        cleanupFns.push(() => gsap.ticker.remove(onTick));

        const onDown = (e) => {
          state.dragging = true;
          state.lastX = e.clientX;
          zone.setPointerCapture?.(e.pointerId);
        };
        const onMove = (e) => {
          if (!state.dragging) return;
          const dx = e.clientX - state.lastX;
          state.lastX = e.clientX;
          state.rot += dx * 0.22;
          state.vel = dx * 0.22;
          gsap.set(ring, { rotationY: state.rot });
        };
        const onUp = () => { state.dragging = false; };
        zone.addEventListener("pointerdown", onDown);
        zone.addEventListener("pointermove", onMove);
        window.addEventListener("pointerup", onUp);
        cleanupFns.push(() => {
          zone.removeEventListener("pointerdown", onDown);
          zone.removeEventListener("pointermove", onMove);
          window.removeEventListener("pointerup", onUp);
        });

        /* curseur custom "Drag or click" */
        if (cursor) {
          const pos = { x: 0, y: 0, tx: 0, ty: 0, on: false };
          const onCursorMove = (e) => { pos.tx = e.clientX; pos.ty = e.clientY; };
          const onEnter = () => { pos.on = true; };
          const onLeave = () => { pos.on = false; };
          const onCursorTick = () => {
            pos.x += (pos.tx - pos.x) * 0.14;
            pos.y += (pos.ty - pos.y) * 0.14;
            gsap.set(cursor, { x: pos.x, y: pos.y, scale: pos.on ? 1 : 0 });
          };
          window.addEventListener("mousemove", onCursorMove);
          zone.addEventListener("mouseenter", onEnter);
          zone.addEventListener("mouseleave", onLeave);
          gsap.ticker.add(onCursorTick);
          cleanupFns.push(() => {
            window.removeEventListener("mousemove", onCursorMove);
            zone.removeEventListener("mouseenter", onEnter);
            zone.removeEventListener("mouseleave", onLeave);
            gsap.ticker.remove(onCursorTick);
          });
        }
      }
    },
    { scope: root }
  );

  const n = work.items.length;
  const angle = 360 / n;
  // rayon du cylindre : assez grand pour que les cartes ne se chevauchent pas
  const radius = Math.round((352 / 2) / Math.tan(Math.PI / n) + 120);

  return (
    <div className={`pp ${reduced ? "pp-reduced" : ""} ${className}`} ref={root}>
      <style>{CSS}</style>

      {/* fond ambiant */}
      <div className="pp-glow" ref={glowRef} aria-hidden="true" />

      {/* nav : slot ou barre minimale */}
      {nav || (
        <nav className="pp-nav">
          <a href="#" className="pp-logo" ref={logoRef} aria-label={brand}>
            {brand.split("").map((ch, i) => (
              <span key={i}>{ch}</span>
            ))}
          </a>
          <BloomButton text="Get in touch" href="#contact" />
        </nav>
      )}

      {/* ---------- HERO ---------- */}
      <header className="pp-hero" data-colors="purple,yellow,.4">
        <div className="pp-wrap" style={{ width: "100%" }}>
          <div className="pp-hero-media" data-pp-animate="150">
            <div className="pp-hero-media-inner">
              {hero.video ? (
                <video src={hero.video} muted autoPlay loop playsInline />
              ) : hero.image ? (
                <img src={hero.image} alt="" />
              ) : (
                <div className="pp-media-fallback" />
              )}
            </div>
          </div>
          <div className="pp-hero-text">
            <SplitLines lines={hero.lines} />
            <div data-pp-animate="450">
              <BloomButton text={hero.cta.text} href={hero.cta.href} />
            </div>
          </div>
        </div>
      </header>

      {/* ---------- SELECTED WORK ---------- */}
      <section className="pp-work" id="work" data-colors="purple,black,.5">
        <div className="pp-wrap">
          <div className="pp-work-head">
            <span className="pp-label" data-pp-animate>{work.label}</span>
            <p className="pp-work-intro" data-pp-animate="120">{work.intro}</p>
          </div>
        </div>
        <div className="pp-carousel" ref={carouselRef} data-pp-animate="200">
          <div className="pp-carousel-ring" ref={ringRef}>
            {work.items.map((item, i) => (
              <a
                key={i}
                className="pp-card"
                href={item.href || "#"}
                style={{ transform: `rotateY(${i * angle}deg) translateZ(${radius}px)` }}
                draggable="false"
              >
                <CardMedia item={item} />
                <p>{item.title}</p>
                <h3>{item.client}</h3>
                <span className="pp-label">{item.tags}</span>
              </a>
            ))}
          </div>
        </div>
        <div className="pp-cursor" ref={cursorRef} aria-hidden="true">
          <p>Drag<br />or click</p>
        </div>
      </section>

      {/* ---------- INSIGHTS ---------- */}
      <section className="pp-insights" data-colors="turquoise,purple,.5">
        <div className="pp-wrap">
          <span className="pp-label" data-pp-animate>{insights.label}</span>
          <ul className="pp-insights-list">
            {insights.items.map((item, i) => (
              <li className="pp-insight" key={i} data-pp-animate={i * 80}>
                <a href={item.href}>
                  <span className="pp-label">{item.tag}</span>
                  <h4>{item.title}</h4>
                  <span className="pp-link">Continue reading</span>
                </a>
              </li>
            ))}
          </ul>
        </div>
      </section>

      {/* ---------- CTA GÉANT ---------- */}
      <section className="pp-cta" id="contact" data-colors="purple,yellow,.4">
        <div className="pp-wrap">
          <div className="pp-cta-text" data-pp-animate>
            <h2 className="pp-title-lg">
              {cta.lines.map((l, i) => (
                <span key={i}>{l}</span>
              ))}
            </h2>
            <div className="pp-cta-btn">
              <BloomButton text={cta.button.text} href={cta.button.href} />
            </div>
          </div>
        </div>
      </section>

      {/* ---------- FOOTER ---------- */}
      <footer className="pp-footer">
        <div className="pp-wrap">
          <div className="pp-footer-grid">
            <div>
              <span className="pp-label">{footer.newsletterLabel}</span>
              <h3>{footer.newsletterTitle}</h3>
              <form className="pp-news-form" onSubmit={(e) => e.preventDefault()}>
                <input type="email" placeholder="Your email" aria-label="Votre email" />
                <button className="pp-news-btn" type="submit" aria-label="S'inscrire">
                  <svg width="14" height="14" viewBox="0 0 14 14" fill="none" aria-hidden="true">
                    <path d="M1 7h11M8 2.5 12.5 7 8 11.5" stroke="currentColor" strokeWidth="2" />
                  </svg>
                </button>
              </form>
            </div>
            <div>
              <span className="pp-label">{footer.contactLabel}</span>
              <div className="pp-footer-contact">
                <div><a href={`mailto:${footer.email}`}>{footer.email}</a></div>
                <div><a href={`tel:${footer.phone.replace(/[^+\d]/g, "")}`}>{footer.phone}</a></div>
              </div>
              <address className="pp-footer-addr">
                {footer.address.map((l, i) => (
                  <div key={i}>{l}</div>
                ))}
              </address>
            </div>
          </div>
          <div className="pp-footer-bottom">
            <div className="pp-footer-socials">
              <span>{footer.socialsLabel}</span>
              {footer.socials.map((s) => (
                <a key={s.label} href={s.href} target="_blank" rel="noreferrer">{s.label}</a>
              ))}
            </div>
            <div className="pp-footer-socials">
              {footer.legal.map((l) => (
                <a key={l} href="#">{l}</a>
              ))}
              <span>© {new Date().getFullYear()} {brand}</span>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
}

